115: export function joinBase(envUrl: string, base: string): string {
116:   const b = base.trim();
117:   if (/^https?:\/\//i.test(b)) return b.replace(/\/+$/, '');
118:   const prefix = envUrl.replace(/\/+$/, '');
119:   if (b === '') return prefix;
120:   return `${prefix}${b.startsWith('/') ? '' : '/'}${b.replace(/\/+$/, '')}`;
121: }
