123: export function authHeaders(auth: AuthScheme, key: string): Record<string, string> {
124:   if (key === '') return {};
125:   if (auth === 'bearer') return { authorization: `Bearer ${key}` };
126:   if (auth === 'x-api-key') return { 'x-api-key': key };
127:   if (auth === 'x-goog-api-key') return { 'x-goog-api-key': key };
128:   return {};
129: }
