131: function documentsIn(text: string): Json[] {
132:   const out: Json[] = [];
133:   for (let start = text.indexOf('{'); start !== -1; start = text.indexOf('{', start + 1)) {
134:     const end = objectEnd(text, start);
135:     if (end === -1) continue;
136:     try {
137:       const value: unknown = JSON.parse(text.slice(start, end + 1));
138:       if (isRecord(value) && typeof value.schema === 'string') out.push(value);
139:     } catch {
140:       // Continue scanning.
141:     }
142:   }
143:   return out;
144: }
