146: function objectEnd(text: string, start: number): number {
147:   let depth = 0;
148:   let inString = false;
149:   for (let i = start; i < text.length; i++) {
150:     const ch = text[i];
151:     if (inString) {
152:       if (ch === '\\') i += 1;
153:       else if (ch === '"') inString = false;
154:     } else if (ch === '"') inString = true;
155:     else if (ch === '{') depth += 1;
156:     else if (ch === '}') {
157:       depth -= 1;
158:       if (depth === 0) return i;
159:     }
160:   }
161:   return -1;
162: }
