212:     stream: v.stream === true,
213:     weight: v.weight === 2 ? 2 : 1,
214:     requires: {
215:       tools: requires.tools === true,
216:       vision: requires.vision === true,
217:       json: requires.json === true,
218:       ...(typeof requires.min_context === 'number' && Number.isFinite(requires.min_context) ? { min_context: requires.min_context } : {}),
