223: export function readBrief(path: string): Brief {
224:   const directory: ProviderDirectory = { schema: PROVIDERS_SCHEMA, providers: [] };
225:   if (path === '') return { directory, ratings: null, workload: null, error: 'MAKEFUN_PROMPT_FILE is not set' };
226:   let text: string;
227:   try {
228:     text = readFileSync(path, 'utf8');
229:   } catch (err) {
230:     return { directory, ratings: null, workload: null, error: `cannot read ${path}: ${(err as Error).message}` };
231:   }
232:   const docs = documentsIn(text);
233:   const directoryDoc = docs.find((d) => d.schema === PROVIDERS_SCHEMA && Array.isArray(d.providers)) ?? null;
234:   if (directoryDoc === null || !Array.isArray(directoryDoc.providers)) {
235:     return { directory, ratings: null, workload: null, error: `the brief at ${path} holds no ${PROVIDERS_SCHEMA} document` };
236:   }
237:   const providers = directoryDoc.providers.flatMap((v) => {
238:     const p = providerOf(v);
239:     return p === null ? [] : [p];
240:   });
241:   const ratingsDoc = docs.find((d) => d.schema === RATINGS_SCHEMA && Array.isArray(d.ratings)) ?? null;
242:   const ratingRows = ratingsDoc !== null && Array.isArray(ratingsDoc.ratings) ? ratingsDoc.ratings : null;
243:   const ratings: RatingsFile | null =
244:     ratingsDoc === null || ratingRows === null
245:       ? null
246:       : {
247:           schema: RATINGS_SCHEMA,
248:           ratings: ratingRows.flatMap((v) => {
249:             const r = ratingOf(v);
250:             return r === null ? [] : [r];
251:           }),
252:           best: Array.isArray(ratingsDoc.best)
253:             ? ratingsDoc.best.flatMap((v) => {
254:                 if (!isRecord(v) || stringOf(v.id) === '') return [];
255:                 return [{ id: stringOf(v.id), rating_milli: numberOrNull(v.rating_milli) ?? 0 }];
256:               })
257:             : [],
258:         };
259:   const workloadDoc = docs.find((d) => d.schema === WORKLOAD_SCHEMA && Array.isArray(d.manifest)) ?? null;
260:   const workload: WorkloadFile | null =
261:     workloadDoc === null || !Array.isArray(workloadDoc.manifest)
262:       ? null
263:       : {
264:           schema: WORKLOAD_SCHEMA,
265:           manifest: workloadDoc.manifest.flatMap((v) => {
266:             const w = workloadRequestOf(v);
267:             return w === null ? [] : [w];
268:           }),
269:         };
270:   return { directory: { schema: PROVIDERS_SCHEMA, providers }, ratings, workload, error: null };
271: }
