273: export function ratingOfModel(ratings: RatingsFile | null, providerId: string, modelId: string): RatingRow | null {
274:   if (ratings === null) return null;
275:   return ratings.ratings.find((r) => r.provider === providerId && r.model === modelId) ?? null;
276: }
