285:     context_length: row?.context_length ?? model.context_length ?? null,
286:     tools: row?.tools ?? model.tools ?? null,
287:     vision: row?.vision ?? model.vision ?? null,
288:     json: row?.json ?? model.json ?? null,
289:   };
