292: export function meetsRequirements(requires: Requirement, caps: Capabilities): boolean {
293:   if (requires.tools === true && caps.tools !== true) return false;
294:   if (requires.vision === true && caps.vision !== true) return false;
295:   if (requires.json === true && caps.json !== true) return false;
296:   if (requires.min_context !== undefined && (caps.context_length === null || caps.context_length < requires.min_context)) return false;
297:   return true;
298: }
