300: function zeroPriced(v: Json): boolean | null {
301:   const pricing = isRecord(v.pricing) ? v.pricing : null;
302:   if (pricing === null) return null;
303:   const values = Object.values(pricing).flatMap((x) => {
304:     if (typeof x === 'number') return [x];
305:     if (typeof x === 'string' && x.trim() !== '') return [Number(x)];
306:     return [];
307:   });
308:   if (values.length === 0) return null;
309:   return values.every((n) => Number.isFinite(n) && n === 0);
310: }
