312: function modelIn(wire: Wire, v: unknown): ProbedModel | null {
313:   if (!isRecord(v)) return null;
314:   const id = wire === 'gemini' ? stringOf(v.name).replace(/^models\//, '') : stringOf(v.id);
315:   if (id === '') return null;
316:   const context = numberOrNull(v.context_length) ?? numberOrNull(v.context_window) ?? numberOrNull(v.inputTokenLimit);
317:   return {
318:     id,
319:     display_name: stringOf(v.display_name) !== '' ? stringOf(v.display_name) : stringOf(v.displayName) !== '' ? stringOf(v.displayName) : id,
320:     free: boolOrNull(v.free) ?? zeroPriced(v),
321:     context_length: context,
322:     tools: boolOrNull(v.tools),
323:     vision: boolOrNull(v.vision),
324:     json: boolOrNull(v.json),
325:   };
326: }
327: 
328: function modelsIn(wire: Wire, body: unknown): ProbedModel[] {
329:   if (!isRecord(body)) return [];
330:   const list = wire === 'gemini' ? body.models : body.data;
331:   if (!Array.isArray(list)) return [];
332:   return list.flatMap((v) => {
333:     const m = modelIn(wire, v);
334:     return m === null ? [] : [m];
335:   });
336: }
