338: export async function probeProvider(
339:   envUrl: string,
340:   provider: ProviderDirectoryEntry,
341:   timeoutMs = 5000,
342:   ratings: RatingsFile | null = null,
343: ): Promise<Probe> {
344:   if (envUrl.trim() === '' && ratings !== null) {
345:     const models: ProbedModel[] = ratings.ratings
346:       .filter((r) => r.provider === provider.id)
347:       .map((r) => ({
348:         id: r.model,
349:         display_name: r.model,
350:         free: r.free,
351:         context_length: r.context_length,
352:         tools: r.tools,
353:         vision: r.vision,
354:         json: r.json,
355:       }));
356:     return { provider, ok: true, status: 200, models, error: null };
357:   }
358:   const base = joinBase(envUrl, provider.base);
359:   const url = provider.wire === 'gemini' ? `${base}/v1beta/models` : `${base}/v1/models`;
360:   const headers: Record<string, string> = { accept: 'application/json', ...authHeaders(provider.auth, provider.key) };
361:   if (provider.wire === 'anthropic') headers['anthropic-version'] = '2023-06-01';
362:   try {
363:     const res = await fetch(url, { headers, signal: AbortSignal.timeout(timeoutMs) });
364:     if (!res.ok) return { provider, ok: false, status: res.status, models: [], error: `GET ${url} answered HTTP ${res.status}` };
365:     const body: unknown = await res.json();
366:     return { provider, ok: true, status: res.status, models: modelsIn(provider.wire, body), error: null };
367:   } catch (err) {
368:     return { provider, ok: false, status: 0, models: [], error: `GET ${url} failed: ${(err as Error).message}` };
369:   }
370: }
371: 
372: export function buildCatalog(_envUrl: string, probes: readonly Probe[], ratings: RatingsFile | null): CatalogReport {
373:   const providers: CatalogProvider[] = [];
374:   for (const probe of probes) {
375:     if (!probe.ok) continue;
376:     const seen = new Set<string>();
377:     const models: CatalogModel[] = [];
378:     for (const model of [...probe.models].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))) {
379:       if (seen.has(model.id)) continue;
380:       seen.add(model.id);
381:       const row = ratingOfModel(ratings, probe.provider.id, model.id);
382:       models.push({ id: model.id, free: modelFree(model, row), context_length: row?.context_length ?? model.context_length ?? null });
383:     }
384:     providers.push({ id: probe.provider.id, base_url: probe.provider.base, key_env: probe.provider.key_env, wire: probe.provider.wire, models });
385:   }
386:   return { providers };
387: }

