315:         ? `${base}/v1/messages`
316:         : `${base}/v1beta/models/${encodeURIComponent(cand.model.id)}:generateContent`;
317:   const headers: Record<string, string> = {
318:     'content-type': 'application/json',
319:     accept: 'application/json',
320:     ...authHeaders(provider.auth, provider.key),
321:   };
322:   if (provider.wire === 'anthropic') headers['anthropic-version'] = '2023-06-01';
323:   const upstreamBody = buildUpstreamBody(provider.wire, cand.model.id, req);
324: 
325:   const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(upstreamBody) });
326:   const rawText = await res.text();
327:   if (res.ok) {
328:     let parsedJson: unknown = {};
329:     try {
330:       parsedJson = JSON.parse(rawText);
331:     } catch {
332:       parsedJson = {};
333:     }
334:     const answer = parseUpstreamAnswer(provider.wire, isRecord(parsedJson) ? parsedJson : {});
335:     return { ok: true, answer, permanentDead: false };
336:   }
337: 
338:   // Distinguish permanent exhaustion/outage ("budget is spent" / "is out") from single-call fail_calls ("refused this call")
339:   const permanentDead =
340:     res.status === 401 ||
341:     res.status === 403 ||
342:     rawText.includes('budget is spent') ||
343:     rawText.includes('is out');
344:   return { ok: false, answer: null, permanentDead };
345: }
346: 
347: async function serveInference(req: IncomingMessage, res: ServerResponse, clientApi: 'openai' | 'anthropic'): Promise<void> {
348:   const body = await readJson(req);
349:   if (body === null) return sendError(res, clientApi, 400, 'invalid_request_error', 'the request body is not one JSON object');
350: 
351:   const idx = manifestIndex;
352:   manifestIndex += 1;
353:   const manifestEntry = brief.workload?.manifest[idx];
354:   const parsed = parseClientRequest(clientApi, body);
355:   const requires = mergeRequirements(manifestEntry?.requires, parsed);
356:   const { candidates, topRating, weight } = rankCandidates(requires, parsed, idx, manifestEntry);
357: 
358:   if (candidates.length === 0) {
359:     return sendError(res, clientApi, 503, 'overloaded_error', 'no free model on the directory meets this request');
360:   }
361: 
362:   for (let pass = 0; pass < 3; pass++) {
363:     for (const cand of candidates) {
364:       const st = stateOf(cand.probe.provider.id);
365:       if (st.dead) continue;
366:       st.calls += 1;
367:       try {
368:         const outcome = await callUpstream(cand, parsed);
369:         if (outcome.ok && outcome.answer !== null) {
370:           st.lastCallFailed = false;
371:           const credit = Math.min(cand.rating, topRating);
372:           lossSoFar += weight * (topRating - credit);
373:           if (parsed.stream) {
374:             sendSse(res, emitClientSse(clientApi, outcome.answer, cand.model.id));
375:           } else {
376:             sendJson(res, 200, emitClientJson(clientApi, outcome.answer, cand.model.id));
377:           }
378:           return;
379:         }
380:         totalRefusals += 1;
381:         st.lastCallFailed = true;
382:         if (outcome.permanentDead) {
383:           st.dead = true;
384:         } else {
385:           st.transientFails += 1;
386:         }
387:       } catch {
388:         totalRefusals += 1;
389:         st.lastCallFailed = true;
390:         st.transientFails += 1;
391:       }
392:     }
393:   }
394: 
395:   sendError(res, clientApi, 503, 'overloaded_error', 'all candidate providers refused');
396: }
397: 
398: async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
399:   const url = new URL(req.url ?? '/', 'http://entry');
400:   if (req.method === 'GET' && url.pathname === '/v1/models') {
401:     models(req, res);
402:     return;
403:   }
404:   if (req.method === 'POST' && url.pathname === '/v1/chat/completions') {
405:     await serveInference(req, res, 'openai');
406:     return;
407:   }
408:   if (req.method === 'POST' && url.pathname === '/v1/messages') {
409:     await serveInference(req, res, 'anthropic');
410:     return;
411:   }
412:   sendError(res, url.pathname === '/v1/messages' ? 'anthropic' : 'openai', 404, 'not_found', `no route ${req.method ?? ''} ${url.pathname}`);
413: }
414: 
415: function listen(server: Server): Promise<void> {
416:   return new Promise((resolve, reject) => {
417:     server.once('error', reject);
418:     server.listen(0, '0.0.0.0', () => resolve());
419:   });
420: }
421: 
422: async function register(port: number, report: CatalogReport): Promise<void> {
423:   const res = await fetch(`${ENV_URL}/register`, {
424:     method: 'POST',
425:     headers: { 'content-type': 'application/json' },
426:     body: JSON.stringify({ protocol_version: PROTOCOL_VERSION, port, catalog: report }),
427:     signal: AbortSignal.timeout(5000),
428:   });
429:   if (!res.ok) throw new Error(`POST ${ENV_URL}/register answered HTTP ${res.status}: ${(await res.text()).slice(0, 500)}`);
430:   const reply: unknown = await res.json();
431:   if (isRecord(reply) && typeof reply.requests === 'number') log(`registered: the workload holds ${reply.requests} requests`);
432: }
433: 
434: function poll(server: Server): void {
435:   let inFlight = false;
436:   const timer = setInterval(() => {
437:     if (inFlight) return;
438:     inFlight = true;
439:     void (async () => {
440:       try {
441:         const res = await fetch(`${ENV_URL}/work`, { signal: AbortSignal.timeout(2000) });
442:         if (res.status !== 200) return;
443:         const work: unknown = await res.json();
444:         if (isRecord(work) && work.done === true) {
445:           clearInterval(timer);
446:           server.close();
447:           process.exit(0);
448:         }
449:       } catch {
450:         // Retry on next tick.
451:       } finally {
452:         inFlight = false;
453:       }
454:     })();
455:   }, POLL_INTERVAL_MS);
456: }
457: 
458: async function start(): Promise<void> {
459:   await load();
460:   if (process.argv.includes('--list')) {
461:     const text = `${JSON.stringify(catalog)}\n`;
462:     await new Promise<void>((resolve) => process.stdout.write(text, () => resolve()));
463:     process.exit(0);
464:   }
465:   if (ENV_URL === '') throw new Error('MAKEFUN_ENV_URL is not set');
466:   const server = createServer((req, res) => {
467:     void handle(req, res).catch((err: unknown) => {
468:       log((err as Error).stack ?? String(err));
469:       if (!res.headersSent) sendError(res, req.url?.startsWith('/v1/messages') === true ? 'anthropic' : 'openai', 500, 'internal_error', 'the server failed to answer');
470:     });
471:   });
472:   await listen(server);
473:   const address = server.address();
474:   if (address === null || typeof address === 'string') throw new Error('the server has no port');
475:   const port = address.port;
476:   if (port === 8080) throw new Error('the OS picked 8080, which the env owns on one layout: restart the trial');
477:   log(`listening on 0.0.0.0:${port} with ${catalog.providers.length} answered providers and ${servedModels().length} free models`);
478:   await register(port, catalog);
479:   process.on('SIGTERM', () => process.exit(0));
480:   process.on('SIGINT', () => process.exit(0));
481:   poll(server);
482: }
483: 
484: try {
485:   await start();
486: } catch (err) {
487:   log((err as Error).stack ?? String(err));
488:   process.exit(1);
489: }

