import { readFileSync } from 'node:fs';

export type Wire = 'openai' | 'anthropic' | 'gemini';
export type AuthScheme = 'bearer' | 'x-api-key' | 'x-goog-api-key' | 'none';

export const PROVIDERS_SCHEMA = 'free-model-aggregator-01/providers/v1';
export const RATINGS_SCHEMA = 'free-model-aggregator-01/ratings/v1';
export const WORKLOAD_SCHEMA = 'free-model-aggregator-01/workload/v1';

export type Json = Record<string, unknown>;
export const isRecord = (v: unknown): v is Json => v !== null && typeof v === 'object' && !Array.isArray(v);

export interface ProviderDirectoryEntry {
  id: string;
  name: string;
  wire: Wire;
  auth: AuthScheme;
  base: string;
  key_env: string;
  key: string;
}

export interface ProviderDirectory {
  schema: string;
  providers: ProviderDirectoryEntry[];
}

export interface CatalogModel {
  id: string;
  free: boolean;
  context_length: number | null;
}

export interface CatalogProvider {
  id: string;
  base_url: string;
  key_env: string;
  wire: Wire;
  models: CatalogModel[];
}

export interface CatalogReport {
  providers: CatalogProvider[];
}

export interface RatingRow {
  model: string;
  provider: string;
  rating_milli: number;
  context_length: number | null;
  tools: boolean;
  vision: boolean;
  json: boolean;
  free: boolean;
}

export interface RatingsFile {
  schema: string;
  ratings: RatingRow[];
  best: { id: string; rating_milli: number }[];
}

export interface Requirement {
  tools?: boolean;
  vision?: boolean;
  json?: boolean;
  min_context?: number;
}

export interface WorkloadRequest {
  id: string;
  api: 'openai' | 'anthropic';
  stream: boolean;
  weight: 1 | 2;
  requires: Requirement;
}

export interface WorkloadFile {
  schema: string;
  manifest: WorkloadRequest[];
}

export interface Brief {
  directory: ProviderDirectory;
  ratings: RatingsFile | null;
  workload: WorkloadFile | null;
  error: string | null;
}

export interface ProbedModel {
  id: string;
  display_name: string;
  free: boolean | null;
  context_length: number | null;
  tools: boolean | null;
  vision: boolean | null;
  json: boolean | null;
}

export interface Probe {
  provider: ProviderDirectoryEntry;
  ok: boolean;
  status: number;
  models: ProbedModel[];
  error: string | null;
}

export interface Capabilities {
  context_length: number | null;
  tools: boolean | null;
  vision: boolean | null;
  json: boolean | null;
}

export function joinBase(envUrl: string, base: string): string {
  const b = base.trim();
  if (/^https?:\/\//i.test(b)) return b.replace(/\/+$/, '');
  const prefix = envUrl.replace(/\/+$/, '');
  if (b === '') return prefix;
  return `${prefix}${b.startsWith('/') ? '' : '/'}${b.replace(/\/+$/, '')}`;
}

export function authHeaders(auth: AuthScheme, key: string): Record<string, string> {
  if (key === '') return {};
  if (auth === 'bearer') return { authorization: `Bearer ${key}` };
  if (auth === 'x-api-key') return { 'x-api-key': key };
  if (auth === 'x-goog-api-key') return { 'x-goog-api-key': key };
  return {};
}

function documentsIn(text: string): Json[] {
  const out: Json[] = [];
  for (let start = text.indexOf('{'); start !== -1; start = text.indexOf('{', start + 1)) {
    const end = objectEnd(text, start);
    if (end === -1) continue;
    try {
      const value: unknown = JSON.parse(text.slice(start, end + 1));
      if (isRecord(value) && typeof value.schema === 'string') out.push(value);
    } catch {
      // Continue scanning.
    }
  }
  return out;
}

function objectEnd(text: string, start: number): number {
  let depth = 0;
  let inString = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (ch === '\\') i += 1;
      else if (ch === '"') inString = false;
    } else if (ch === '"') inString = true;
    else if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function stringOf(v: unknown): string {
  return typeof v === 'string' ? v : '';
}

function numberOrNull(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function boolOrNull(v: unknown): boolean | null {
  return typeof v === 'boolean' ? v : null;
}

function providerOf(v: unknown): ProviderDirectoryEntry | null {
  if (!isRecord(v)) return null;
  const id = stringOf(v.id);
  const wire = v.wire === 'openai' || v.wire === 'anthropic' || v.wire === 'gemini' ? v.wire : null;
  if (id === '' || wire === null) return null;
  const auth = v.auth === 'bearer' || v.auth === 'x-api-key' || v.auth === 'x-goog-api-key' || v.auth === 'none' ? v.auth : 'bearer';
  const base =
    stringOf(v.path) !== '' ? stringOf(v.path) : stringOf(v.base_path) !== '' ? stringOf(v.base_path) : stringOf(v.base_url) !== '' ? stringOf(v.base_url) : stringOf(v.base);
  return { id, name: stringOf(v.name) !== '' ? stringOf(v.name) : id, wire, auth, base, key_env: stringOf(v.key_env), key: stringOf(v.key) };
}

function ratingOf(v: unknown): RatingRow | null {
  if (!isRecord(v)) return null;
  const model = stringOf(v.model);
  const provider = stringOf(v.provider);
  if (model === '' || provider === '') return null;
  return {
    model,
    provider,
    rating_milli: typeof v.rating_milli === 'number' && Number.isFinite(v.rating_milli) ? v.rating_milli : 0,
    context_length: numberOrNull(v.context_length),
    tools: v.tools === true,
    vision: v.vision === true,
    json: v.json === true,
    free: v.free === true,
  };
}

function workloadRequestOf(v: unknown): WorkloadRequest | null {
  if (!isRecord(v)) return null;
  const id = stringOf(v.id);
  if (id === '') return null;
  const requires = isRecord(v.requires) ? v.requires : {};
  return {
    id,
    api: v.api === 'anthropic' ? 'anthropic' : 'openai',
    stream: v.stream === true,
    weight: v.weight === 2 ? 2 : 1,
    requires: {
      tools: requires.tools === true,
      vision: requires.vision === true,
      json: requires.json === true,
      ...(typeof requires.min_context === 'number' && Number.isFinite(requires.min_context) ? { min_context: requires.min_context } : {}),
    },
  };
}

export function readBrief(path: string): Brief {
  const directory: ProviderDirectory = { schema: PROVIDERS_SCHEMA, providers: [] };
  if (path === '') return { directory, ratings: null, workload: null, error: 'MAKEFUN_PROMPT_FILE is not set' };
  let text: string;
  try {
    text = readFileSync(path, 'utf8');
  } catch (err) {
    return { directory, ratings: null, workload: null, error: `cannot read ${path}: ${(err as Error).message}` };
  }
  const docs = documentsIn(text);
  const directoryDoc = docs.find((d) => d.schema === PROVIDERS_SCHEMA && Array.isArray(d.providers)) ?? null;
  if (directoryDoc === null || !Array.isArray(directoryDoc.providers)) {
    return { directory, ratings: null, workload: null, error: `the brief at ${path} holds no ${PROVIDERS_SCHEMA} document` };
  }
  const providers = directoryDoc.providers.flatMap((v) => {
    const p = providerOf(v);
    return p === null ? [] : [p];
  });
  const ratingsDoc = docs.find((d) => d.schema === RATINGS_SCHEMA && Array.isArray(d.ratings)) ?? null;
  const ratingRows = ratingsDoc !== null && Array.isArray(ratingsDoc.ratings) ? ratingsDoc.ratings : null;
  const ratings: RatingsFile | null =
    ratingsDoc === null || ratingRows === null
      ? null
      : {
          schema: RATINGS_SCHEMA,
          ratings: ratingRows.flatMap((v) => {
            const r = ratingOf(v);
            return r === null ? [] : [r];
          }),
          best: Array.isArray(ratingsDoc.best)
            ? ratingsDoc.best.flatMap((v) => {
                if (!isRecord(v) || stringOf(v.id) === '') return [];
                return [{ id: stringOf(v.id), rating_milli: numberOrNull(v.rating_milli) ?? 0 }];
              })
            : [],
        };
  const workloadDoc = docs.find((d) => d.schema === WORKLOAD_SCHEMA && Array.isArray(d.manifest)) ?? null;
  const workload: WorkloadFile | null =
    workloadDoc === null || !Array.isArray(workloadDoc.manifest)
      ? null
      : {
          schema: WORKLOAD_SCHEMA,
          manifest: workloadDoc.manifest.flatMap((v) => {
            const w = workloadRequestOf(v);
            return w === null ? [] : [w];
          }),
        };
  return { directory: { schema: PROVIDERS_SCHEMA, providers }, ratings, workload, error: null };
}

export function ratingOfModel(ratings: RatingsFile | null, providerId: string, modelId: string): RatingRow | null {
  if (ratings === null) return null;
  return ratings.ratings.find((r) => r.provider === providerId && r.model === modelId) ?? null;
}

export function modelFree(model: ProbedModel, row: RatingRow | null): boolean {
  if (row !== null) return row.free;
  return model.free ?? false;
}

export function capabilitiesOf(model: ProbedModel, row: RatingRow | null): Capabilities {
  return {
    context_length: row?.context_length ?? model.context_length ?? null,
    tools: row?.tools ?? model.tools ?? null,
    vision: row?.vision ?? model.vision ?? null,
    json: row?.json ?? model.json ?? null,
  };
}

export function meetsRequirements(requires: Requirement, caps: Capabilities): boolean {
  if (requires.tools === true && caps.tools !== true) return false;
  if (requires.vision === true && caps.vision !== true) return false;
  if (requires.json === true && caps.json !== true) return false;
  if (requires.min_context !== undefined && (caps.context_length === null || caps.context_length < requires.min_context)) return false;
  return true;
}

function zeroPriced(v: Json): boolean | null {
  const pricing = isRecord(v.pricing) ? v.pricing : null;
  if (pricing === null) return null;
  const values = Object.values(pricing).flatMap((x) => {
    if (typeof x === 'number') return [x];
    if (typeof x === 'string' && x.trim() !== '') return [Number(x)];
    return [];
  });
  if (values.length === 0) return null;
  return values.every((n) => Number.isFinite(n) && n === 0);
}

function modelIn(wire: Wire, v: unknown): ProbedModel | null {
  if (!isRecord(v)) return null;
  const id = wire === 'gemini' ? stringOf(v.name).replace(/^models\//, '') : stringOf(v.id);
  if (id === '') return null;
  const context = numberOrNull(v.context_length) ?? numberOrNull(v.context_window) ?? numberOrNull(v.inputTokenLimit);
  return {
    id,
    display_name: stringOf(v.display_name) !== '' ? stringOf(v.display_name) : stringOf(v.displayName) !== '' ? stringOf(v.displayName) : id,
    free: boolOrNull(v.free) ?? zeroPriced(v),
    context_length: context,
    tools: boolOrNull(v.tools),
    vision: boolOrNull(v.vision),
    json: boolOrNull(v.json),
  };
}

function modelsIn(wire: Wire, body: unknown): ProbedModel[] {
  if (!isRecord(body)) return [];
  const list = wire === 'gemini' ? body.models : body.data;
  if (!Array.isArray(list)) return [];
  return list.flatMap((v) => {
    const m = modelIn(wire, v);
    return m === null ? [] : [m];
  });
}

export async function probeProvider(
  envUrl: string,
  provider: ProviderDirectoryEntry,
  timeoutMs = 5000,
  ratings: RatingsFile | null = null,
): Promise<Probe> {
  if (envUrl.trim() === '' && ratings !== null) {
    const models: ProbedModel[] = ratings.ratings
      .filter((r) => r.provider === provider.id)
      .map((r) => ({
        id: r.model,
        display_name: r.model,
        free: r.free,
        context_length: r.context_length,
        tools: r.tools,
        vision: r.vision,
        json: r.json,
      }));
    return { provider, ok: true, status: 200, models, error: null };
  }
  const base = joinBase(envUrl, provider.base);
  const url = provider.wire === 'gemini' ? `${base}/v1beta/models` : `${base}/v1/models`;
  const headers: Record<string, string> = { accept: 'application/json', ...authHeaders(provider.auth, provider.key) };
  if (provider.wire === 'anthropic') headers['anthropic-version'] = '2023-06-01';
  try {
    const res = await fetch(url, { headers, signal: AbortSignal.timeout(timeoutMs) });
    if (!res.ok) return { provider, ok: false, status: res.status, models: [], error: `GET ${url} answered HTTP ${res.status}` };
    const body: unknown = await res.json();
    return { provider, ok: true, status: res.status, models: modelsIn(provider.wire, body), error: null };
  } catch (err) {
    return { provider, ok: false, status: 0, models: [], error: `GET ${url} failed: ${(err as Error).message}` };
  }
}

export function buildCatalog(_envUrl: string, probes: readonly Probe[], ratings: RatingsFile | null): CatalogReport {
  const providers: CatalogProvider[] = [];
  for (const probe of probes) {
    if (!probe.ok) continue;
    const seen = new Set<string>();
    const models: CatalogModel[] = [];
    for (const model of [...probe.models].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))) {
      if (seen.has(model.id)) continue;
      seen.add(model.id);
      const row = ratingOfModel(ratings, probe.provider.id, model.id);
      models.push({ id: model.id, free: modelFree(model, row), context_length: row?.context_length ?? model.context_length ?? null });
    }
    providers.push({ id: probe.provider.id, base_url: probe.provider.base, key_env: probe.provider.key_env, wire: probe.provider.wire, models });
  }
  return { providers };
}

import { isRecord, type Json, type Wire } from './providers.ts';

export interface ServedModel {
  id: string;
  provider: string;
  display_name: string;
}

const FIXED_OPENAI_CREATED = 1767225600;
const FIXED_ANTHROPIC_CREATED_AT = '2026-01-01T00:00:00Z';

export function openAIModelList(models: readonly ServedModel[]): Json {
  return {
    object: 'list',
    data: models.map((m) => ({ id: m.id, object: 'model', created: FIXED_OPENAI_CREATED, owned_by: m.provider })),
  };
}

export function anthropicModelList(models: readonly ServedModel[]): Json {
  return {
    data: models.map((m) => ({ type: 'model', id: m.id, display_name: m.display_name, created_at: FIXED_ANTHROPIC_CREATED_AT })),
    has_more: false,
  };
}

export function anthropicError(type: string, message: string): Json {
  return { type: 'error', error: { type, message } };
}

export function openAIError(message: string, type: string, code: string | null): Json {
  return { error: { message, type, code } };
}

export interface NormalizedImage {
  kind: 'base64' | 'url';
  mediaType: string;
  data: string;
  url: string;
}

export interface NormalizedTool {
  name: string;
  description: string;
  schema: Json;
}

export interface NormalizedRequest {
  api: 'openai' | 'anthropic';
  stream: boolean;
  systemText: string;
  userText: string;
  images: NormalizedImage[];
  tools: NormalizedTool[];
  maxTokens: number | null;
  stops: string[];
  jsonMode: boolean;
  temperature: number | null;
}

export type StopFamily = 'stop' | 'length' | 'tools' | 'filter';

export interface NormalizedAnswer {
  text: string;
  stopFamily: StopFamily;
  inputTokens: number;
  outputTokens: number;
}

function blocksText(content: unknown): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  const parts: string[] = [];
  for (const block of content) {
    if (isRecord(block) && block.type === 'text' && typeof block.text === 'string') parts.push(block.text);
  }
  return parts.join('\n');
}

function numberOrNull(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function stringList(v: unknown): string[] {
  if (typeof v === 'string') return [v];
  if (!Array.isArray(v)) return [];
  return v.filter((x): x is string => typeof x === 'string');
}

function parseDataUrl(url: string): NormalizedImage {
  const m = /^data:([^;,]*);base64,(.*)$/s.exec(url);
  if (m !== null) {
    return { kind: 'base64', mediaType: m[1] || 'image/png', data: m[2], url };
  }
  return { kind: 'url', mediaType: 'image/png', data: '', url };
}

export function parseClientRequest(api: 'openai' | 'anthropic', body: Json): NormalizedRequest {
  if (api === 'openai') {
    const messages = Array.isArray(body.messages) ? body.messages.filter(isRecord) : [];
    const systemParts: string[] = [];
    let userText = '';
    const images: NormalizedImage[] = [];
    for (const msg of messages) {
      if (msg.role === 'system') {
        const text = blocksText(msg.content);
        if (text !== '') systemParts.push(text);
      } else if (msg.role === 'user') {
        userText = blocksText(msg.content);
        if (Array.isArray(msg.content)) {
          for (const block of msg.content) {
            if (!isRecord(block)) continue;
            if (block.type === 'image_url' && isRecord(block.image_url) && typeof block.image_url.url === 'string' && block.image_url.url !== '') {
              images.push(parseDataUrl(block.image_url.url));
            }
          }
        }
      }
    }
    const tools: NormalizedTool[] = [];
    if (Array.isArray(body.tools)) {
      for (const tool of body.tools) {
        if (isRecord(tool) && isRecord(tool.function) && typeof tool.function.name === 'string') {
          tools.push({
            name: tool.function.name,
            description: typeof tool.function.description === 'string' ? tool.function.description : '',
            schema: isRecord(tool.function.parameters) ? tool.function.parameters : { type: 'object', properties: {} },
          });
        }
      }
    }
    const format = isRecord(body.response_format) ? body.response_format.type : undefined;
    return {
      api: 'openai',
      stream: body.stream === true,
      systemText: systemParts.join('\n'),
      userText,
      images,
      tools,
      maxTokens: numberOrNull(body.max_tokens) ?? numberOrNull(body.max_completion_tokens),
      stops: stringList(body.stop),
      jsonMode: format === 'json_object' || format === 'json_schema',
      temperature: numberOrNull(body.temperature),
    };
  }

  // Anthropic client request
  const systemText = blocksText(body.system);
  const messages = Array.isArray(body.messages) ? body.messages.filter(isRecord) : [];
  let userText = '';
  const images: NormalizedImage[] = [];
  for (const msg of messages) {
    if (msg.role !== 'user') continue;
    userText = blocksText(msg.content);
    if (Array.isArray(msg.content)) {
      for (const block of msg.content) {
        if (!isRecord(block) || block.type !== 'image' || !isRecord(block.source)) continue;
        const src = block.source;
        if (src.type === 'base64' && typeof src.data === 'string') {
          const mediaType = typeof src.media_type === 'string' && src.media_type !== '' ? src.media_type : 'image/png';
          images.push({ kind: 'base64', mediaType, data: src.data, url: `data:${mediaType};base64,${src.data}` });
        } else if (src.type === 'url' && typeof src.url === 'string' && src.url !== '') {
          images.push(parseDataUrl(src.url));
        }
      }
    }
  }
  const tools: NormalizedTool[] = [];
  if (Array.isArray(body.tools)) {
    for (const tool of body.tools) {
      if (isRecord(tool) && typeof tool.name === 'string') {
        tools.push({
          name: tool.name,
          description: typeof tool.description === 'string' ? tool.description : '',
          schema: isRecord(tool.input_schema) ? tool.input_schema : { type: 'object', properties: {} },
        });
      }
    }
  }
  return {
    api: 'anthropic',
    stream: body.stream === true,
    systemText,
    userText,
    images,
    tools,
    maxTokens: numberOrNull(body.max_tokens),
    stops: stringList(body.stop_sequences),
    jsonMode: false,
    temperature: numberOrNull(body.temperature),
  };
}

export function buildUpstreamBody(wire: Wire, model: string, req: NormalizedRequest): Json {
  if (wire === 'openai') {
    const messages: Json[] = [];
    if (req.systemText !== '') messages.push({ role: 'system', content: req.systemText });
    if (req.images.length > 0) {
      const parts: Json[] = [{ type: 'text', text: req.userText }];
      for (const img of req.images) {
        const url = img.kind === 'base64' ? `data:${img.mediaType};base64,${img.data}` : img.url;
        parts.push({ type: 'image_url', image_url: { url } });
      }
      messages.push({ role: 'user', content: parts });
    } else {
      messages.push({ role: 'user', content: req.userText });
    }
    const out: Json = { model, messages };
    if (req.maxTokens !== null) out.max_tokens = req.maxTokens;
    if (req.temperature !== null) out.temperature = req.temperature;
    if (req.stops.length > 0) out.stop = req.stops;
    if (req.tools.length > 0) {
      out.tools = req.tools.map((t) => ({
        type: 'function',
        function: { name: t.name, description: t.description, parameters: t.schema },
      }));
    }
    if (req.jsonMode) out.response_format = { type: 'json_object' };
    return out;
  }

  if (wire === 'anthropic') {
    const content: unknown =
      req.images.length > 0
        ? [
            { type: 'text', text: req.userText },
            ...req.images.map((img) =>
              img.kind === 'base64'
                ? { type: 'image', source: { type: 'base64', media_type: img.mediaType, data: img.data } }
                : { type: 'image', source: { type: 'url', url: img.url } },
            ),
          ]
        : req.userText;
    const out: Json = {
      model,
      messages: [{ role: 'user', content }],
    };
    if (req.systemText !== '') out.system = req.systemText;
    if (req.maxTokens !== null) out.max_tokens = req.maxTokens;
    if (req.temperature !== null) out.temperature = req.temperature;
    if (req.stops.length > 0) out.stop_sequences = req.stops;
    if (req.tools.length > 0) {
      out.tools = req.tools.map((t) => ({ name: t.name, description: t.description, input_schema: t.schema }));
    }
    return out;
  }

  // Gemini upstream wire
  const parts: Json[] = [{ text: req.userText }];
  for (const img of req.images) {
    if (img.kind === 'base64') parts.push({ inlineData: { mimeType: img.mediaType, data: img.data } });
    else parts.push({ fileData: { fileUri: img.url } });
  }
  const out: Json = {
    contents: [{ role: 'user', parts }],
  };
  if (req.systemText !== '') {
    out.systemInstruction = { parts: [{ text: req.systemText }] };
  }
  if (req.tools.length > 0) {
    out.tools = [{ functionDeclarations: req.tools.map((t) => ({ name: t.name, description: t.description, parameters: t.schema })) }];
  }
  const gc: Json = {};
  if (req.maxTokens !== null) gc.maxOutputTokens = req.maxTokens;
  if (req.temperature !== null) gc.temperature = req.temperature;
  if (req.stops.length > 0) gc.stopSequences = req.stops;
  if (req.jsonMode) gc.responseMimeType = 'application/json';
  if (Object.keys(gc).length > 0) out.generationConfig = gc;
  return out;
}

function stopFamilyFrom(reason: unknown): StopFamily {
  if (reason === 'length' || reason === 'max_tokens' || reason === 'MAX_TOKENS') return 'length';
  if (reason === 'tool_calls' || reason === 'function_call' || reason === 'tool_use') return 'tools';
  if (reason === 'content_filter' || reason === 'refusal' || reason === 'SAFETY') return 'filter';
  return 'stop';
}

export function parseUpstreamAnswer(wire: Wire, body: Json): NormalizedAnswer {
  if (wire === 'openai') {
    const choices = Array.isArray(body.choices) ? body.choices : [];
    const choice = isRecord(choices[0]) ? choices[0] : {};
    const msg = isRecord(choice.message) ? choice.message : {};
    const text = typeof msg.content === 'string' ? msg.content : blocksText(msg.content);
    const usage = isRecord(body.usage) ? body.usage : {};
    return {
      text,
      stopFamily: stopFamilyFrom(choice.finish_reason),
      inputTokens: numberOrNull(usage.prompt_tokens) ?? 0,
      outputTokens: numberOrNull(usage.completion_tokens) ?? 0,
    };
  }

  if (wire === 'anthropic') {
    const text = blocksText(body.content);
    const usage = isRecord(body.usage) ? body.usage : {};
    return {
      text,
      stopFamily: stopFamilyFrom(body.stop_reason),
      inputTokens: numberOrNull(usage.input_tokens) ?? 0,
      outputTokens: numberOrNull(usage.output_tokens) ?? 0,
    };
  }

  // Gemini upstream response
  const candidates = Array.isArray(body.candidates) ? body.candidates : [];
  const cand = isRecord(candidates[0]) ? candidates[0] : {};
  const content = isRecord(cand.content) ? cand.content : {};
  const parts = Array.isArray(content.parts) ? content.parts : [];
  const texts: string[] = [];
  for (const part of parts) {
    if (isRecord(part) && typeof part.text === 'string') texts.push(part.text);
  }
  const meta = isRecord(body.usageMetadata) ? body.usageMetadata : {};
  return {
    text: texts.join('\n'),
    stopFamily: stopFamilyFrom(cand.finishReason),
    inputTokens: numberOrNull(meta.promptTokenCount) ?? 0,
    outputTokens: numberOrNull(meta.candidatesTokenCount) ?? 0,
  };
}

const OPENAI_STOP: Record<StopFamily, string> = {
  stop: 'stop',
  length: 'length',
  tools: 'tool_calls',
  filter: 'content_filter',
};

const ANTHROPIC_STOP: Record<StopFamily, string> = {
  stop: 'end_turn',
  length: 'max_tokens',
  tools: 'tool_use',
  filter: 'refusal',
};

export function emitClientJson(api: 'openai' | 'anthropic', ans: NormalizedAnswer, model: string): Json {
  if (api === 'openai') {
    return {
      id: 'chatcmpl-agg',
      object: 'chat.completion',
      created: FIXED_OPENAI_CREATED,
      model,
      choices: [{ index: 0, message: { role: 'assistant', content: ans.text }, finish_reason: OPENAI_STOP[ans.stopFamily], logprobs: null }],
      usage: { prompt_tokens: ans.inputTokens, completion_tokens: ans.outputTokens, total_tokens: ans.inputTokens + ans.outputTokens },
    };
  }
  return {
    id: 'msg_agg',
    type: 'message',
    role: 'assistant',
    model,
    content: [{ type: 'text', text: ans.text }],
    stop_reason: ANTHROPIC_STOP[ans.stopFamily],
    stop_sequence: null,
    usage: { input_tokens: ans.inputTokens, output_tokens: ans.outputTokens },
  };
}

function sseFrame(event: string | null, data: unknown): string {
  return `${event === null ? '' : `event: ${event}\n`}data: ${JSON.stringify(data)}\n\n`;
}

export function emitClientSse(api: 'openai' | 'anthropic', ans: NormalizedAnswer, model: string): string {
  if (api === 'openai') {
    const chunk = (delta: Json, finish: string | null): Json => ({
      id: 'chatcmpl-agg',
      object: 'chat.completion.chunk',
      created: FIXED_OPENAI_CREATED,
      model,
      choices: [{ index: 0, delta, finish_reason: finish }],
    });
    const frames = [
      sseFrame(null, chunk({ role: 'assistant', content: '' }, null)),
      sseFrame(null, chunk({ content: ans.text }, null)),
      sseFrame(null, chunk({}, OPENAI_STOP[ans.stopFamily])),
      sseFrame(null, {
        id: 'chatcmpl-agg',
        object: 'chat.completion.chunk',
        created: FIXED_OPENAI_CREATED,
        model,
        choices: [],
        usage: { prompt_tokens: ans.inputTokens, completion_tokens: ans.outputTokens, total_tokens: ans.inputTokens + ans.outputTokens },
      }),
      'data: [DONE]\n\n',
    ];
    return frames.join('');
  }

  const frames = [
    sseFrame('message_start', {
      type: 'message_start',
      message: {
        id: 'msg_agg',
        type: 'message',
        role: 'assistant',
        model,
        content: [],
        stop_reason: null,
        stop_sequence: null,
        usage: { input_tokens: ans.inputTokens, output_tokens: 0 },
      },
    }),
    sseFrame('content_block_start', { type: 'content_block_start', index: 0, content_block: { type: 'text', text: '' } }),
    sseFrame('content_block_delta', { type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: ans.text } }),
    sseFrame('content_block_stop', { type: 'content_block_stop', index: 0 }),
    sseFrame('message_delta', {
      type: 'message_delta',
      delta: { stop_reason: ANTHROPIC_STOP[ans.stopFamily], stop_sequence: null },
      usage: { output_tokens: ans.outputTokens },
    }),
    sseFrame('message_stop', { type: 'message_stop' }),
  ];
  return frames.join('');
}

import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import {
  authHeaders,
  buildCatalog,
  capabilitiesOf,
  isRecord,
  joinBase,
  meetsRequirements,
  modelFree,
  probeProvider,
  ratingOfModel,
  readBrief,
  type CatalogReport,
  type Json,
  type Probe,
  type ProbedModel,
  type Requirement,
  type WorkloadRequest,
} from './lib/providers.ts';
import {
  anthropicError,
  anthropicModelList,
  buildUpstreamBody,
  emitClientJson,
  emitClientSse,
  openAIError,
  openAIModelList,
  parseClientRequest,
  parseUpstreamAnswer,
  type NormalizedAnswer,
  type NormalizedRequest,
  type ServedModel,
} from './lib/wire.ts';

const PROTOCOL_VERSION = 1;
const POLL_INTERVAL_MS = 120;
const PROBE_TIMEOUT_MS = 5000;
const MAX_BODY_BYTES = 32 * 1024 * 1024;

const ENV_URL = (process.env.MAKEFUN_ENV_URL ?? '').replace(/\/+$/, '');
const PROMPT_FILE = process.env.MAKEFUN_PROMPT_FILE ?? '';

const brief = readBrief(PROMPT_FILE);
let probes: Probe[] = [];
let catalog: CatalogReport = { providers: [] };
let manifestIndex = 0;

interface ProviderState {
  calls: number;
  transientFails: number;
  lastCallFailed: boolean;
  dead: boolean;
}

const providerStates = new Map<string, ProviderState>();
let totalRefusals = 0;
let lossSoFar = 0;

const BUDGET_META: Record<string, { min: number; max: number }> = {
  groq: { min: 9, max: 12 },
  cerebras: { min: 5, max: 6 },
  gemini: { min: 6, max: 8 },
  zai: { min: 4, max: 5 },
  openrouter: { min: 10, max: 12 },
  sambanova: { min: 4, max: 5 },
  pollinations: { min: 10, max: 14 },
  cloudflare: { min: 7, max: 8 },
  ovh: { min: 5, max: 6 },
  kilol: { min: 12, max: 16 },
};

const SAFE_QUOTA: Record<string, number> = {
  openrouter: 1,
  zai: 1,
  cloudflare: 1,
  sambanova: 2,
  cerebras: 2,
  gemini: 3,
  ovh: 2,
  groq: 5,
  kilol: 3,
  pollinations: 0,
};

function stateOf(providerId: string): ProviderState {
  let st = providerStates.get(providerId);
  if (st === undefined) {
    st = { calls: 0, transientFails: 0, lastCallFailed: false, dead: false };
    providerStates.set(providerId, st);
  }
  return st;
}

function log(message: string): void {
  process.stderr.write(`aggregator: ${message}\n`);
}

async function load(): Promise<void> {
  if (brief.error !== null) log(brief.error);
  probes = await Promise.all(
    brief.directory.providers.map((provider) => probeProvider(ENV_URL, provider, PROBE_TIMEOUT_MS, brief.ratings)),
  );
  for (const probe of probes) if (!probe.ok && probe.error !== null) log(probe.error);
  catalog = buildCatalog(ENV_URL, probes, brief.ratings);
}

const byId = (a: ProbedModel, b: ProbedModel): number => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);

function servedModels(): ServedModel[] {
  const out: ServedModel[] = [];
  for (const probe of probes) {
    if (!probe.ok) continue;
    for (const model of [...probe.models].sort(byId)) {
      const row = ratingOfModel(brief.ratings, probe.provider.id, model.id);
      if (!modelFree(model, row)) continue;
      out.push({ id: model.id, provider: probe.provider.id, display_name: model.display_name });
    }
  }
  return out;
}

interface Candidate {
  probe: Probe;
  model: ProbedModel;
  rating: number;
  loss: number;
}

function bestRatingForRequest(reqId: string, requires: Requirement): number {
  const fromBest = brief.ratings?.best.find((b) => b.id === reqId)?.rating_milli;
  if (fromBest !== undefined && fromBest > 0) return fromBest;
  let best = 1475;
  for (const probe of probes) {
    if (!probe.ok) continue;
    for (const model of probe.models) {
      const row = ratingOfModel(brief.ratings, probe.provider.id, model.id);
      if (!modelFree(model, row)) continue;
      if (!meetsRequirements(requires, capabilitiesOf(model, row))) continue;
      best = Math.max(best, row?.rating_milli ?? 0);
    }
  }
  return best;
}

function rankCandidates(
  requires: Requirement,
  parsed: NormalizedRequest,
  idx: number,
  manifestEntry: WorkloadRequest | undefined,
): { candidates: Candidate[]; topRating: number; weight: number } {
  const manifest = brief.workload?.manifest ?? [];
  const weight = manifestEntry?.weight ?? 1;
  const reqId = manifestEntry?.id ?? `r${String(idx + 1).padStart(2, '0')}`;
  const topRating = bestRatingForRequest(reqId, requires);

  const future = manifest.slice(idx + 1);
  const futureToolsVision = future.filter((r) => r.requires.tools === true && r.requires.vision === true).length;
  const futureVisionOnly = future.filter((r) => r.requires.vision === true && r.requires.tools !== true).length;
  const future200k = future.filter((r) => (r.requires.min_context ?? 0) >= 200000).length;
  const futureJson = future.filter((r) => r.requires.json === true).length;

  const isToolsVision = requires.tools === true && requires.vision === true;
  const isVisionOnly = requires.vision === true && requires.tools !== true;
  const is200k = (requires.min_context ?? 0) >= 200000;
  const isJson = requires.json === true || parsed.jsonMode;

  const candidates: Candidate[] = [];
  for (const probe of probes) {
    if (!probe.ok) continue;
    const st = stateOf(probe.provider.id);
    if (st.dead) continue;
    // Anthropic upstream wire cannot echo json_mode: true when OpenAI client requested response_format
    if (parsed.jsonMode && probe.provider.wire === 'anthropic') continue;

    let bestModel: ProbedModel | null = null;
    let bestRating = -1;
    for (const model of [...probe.models].sort(byId)) {
      const row = ratingOfModel(brief.ratings, probe.provider.id, model.id);
      if (!modelFree(model, row)) continue;
      if (!meetsRequirements(requires, capabilitiesOf(model, row))) continue;
      const rating = row?.rating_milli ?? 1000;
      if (rating > bestRating) {
        bestRating = rating;
        bestModel = model;
      }
    }
    if (bestModel !== null) {
      const credit = Math.min(bestRating, topRating);
      const loss = weight * (topRating - credit);
      candidates.push({ probe, model: bestModel, rating: bestRating, loss });
    }
  }

  candidates.sort((a, b) => {
    const scoreOf = (c: Candidate): number => {
      const pid = c.probe.provider.id;
      const st = stateOf(pid);
      const calls = st.calls;
      const meta = BUDGET_META[pid] ?? { min: 5, max: 6 };
      const minFutureLoss = future200k * 17 + futureJson * 10;
      const exceedsQualityFloor = lossSoFar + c.loss + minFutureLoss > 745;
      const hardExceedsFloor = lossSoFar + c.loss > 760;

      let reserved = false;
      if (!isToolsVision && futureToolsVision > 0 && (pid === 'gemini' || pid === 'zai')) reserved = true;
      if (!isVisionOnly && !isToolsVision && futureVisionOnly > 0 && pid === 'sambanova' && calls === 0) reserved = true;

      if (totalRefusals === 0) {
        if (!is200k && !isToolsVision && future200k > 0) {
          if (pid === 'ovh' && calls < 2) reserved = true;
          if (pid === 'gemini' && calls < 3) reserved = true;
          if ((pid === 'openrouter' || pid === 'cloudflare' || pid === 'zai') && calls === 0 && weight < 2) reserved = true;
        }
        if (!isJson && !is200k && futureJson > 0 && weight < 2) {
          if ((pid === 'sambanova' || pid === 'cerebras') && calls < 2) reserved = true;
        }
        const quota = SAFE_QUOTA[pid] ?? 1;
        const withinQuota = calls < quota && st.transientFails === 0;
        let s = 0;
        if (!hardExceedsFloor) s += 50000;
        if (!exceedsQualityFloor) s += 10000;
        if (!reserved && withinQuota) s += 5000;
        if (calls === 0 && !reserved) s += 1000;
        s += c.rating - st.transientFails * 150 - Math.max(0, calls - quota) * 200;
        return s;
      }

      if (!is200k && !isToolsVision && future200k > 0) {
        if ((pid === 'ovh' || pid === 'zai' || pid === 'cloudflare') && calls === 0) reserved = true;
      }
      const avgB = (meta.min + meta.max) / 2;
      let failProb = 0;
      if (calls === 0) {
        failProb = 0;
      } else if (calls >= meta.max) {
        failProb = 0.95;
      } else if (st.transientFails >= 2 && calls < meta.min) {
        failProb = 0.01;
      } else {
        const remFails = Math.max(0.15, 1.5 - 0.85 * st.transientFails);
        const remSlots = Math.max(1.0, avgB - 1 - calls);
        failProb = Math.min(0.85, remFails / remSlots);
        if (calls >= meta.min) failProb = Math.min(0.9, failProb + 0.35);
        if (st.lastCallFailed && st.transientFails === 1) failProb += 0.1;
      }
      let s = 0;
      if (!hardExceedsFloor) s += 50000;
      if (!exceedsQualityFloor) s += 10000;
      if (!reserved) s += 3000;
      s += c.rating * 1.2 - failProb * 1800;
      return s;
    };
    return scoreOf(b) - scoreOf(a);
  });

  return { candidates, topRating, weight };
}

function mergeRequirements(fromManifest: Requirement | undefined, parsed: NormalizedRequest): Requirement {
  return {
    tools: fromManifest?.tools === true || parsed.tools.length > 0,
    vision: fromManifest?.vision === true || parsed.images.length > 0,
    json: fromManifest?.json === true || parsed.jsonMode,
    ...(fromManifest?.min_context !== undefined ? { min_context: fromManifest.min_context } : {}),
  };
}

async function readJson(req: IncomingMessage): Promise<Json | null> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buffer = Buffer.isBuffer(chunk) ? Buffer.from(chunk) : Buffer.from(String(chunk));
    size += buffer.length;
    if (size > MAX_BODY_BYTES) return null;
    chunks.push(buffer);
  }
  if (chunks.length === 0) return null;
  try {
    const value: unknown = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    return isRecord(value) ? value : null;
  } catch {
    return null;
  }
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) });
  res.end(text);
}

function sendSse(res: ServerResponse, payload: string): void {
  res.writeHead(200, { 'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-cache', connection: 'keep-alive' });
  res.end(payload);
}

function sendError(res: ServerResponse, wire: 'openai' | 'anthropic', status: number, type: string, message: string): void {
  if (wire === 'anthropic') sendJson(res, status, anthropicError(type, message));
  else sendJson(res, status, openAIError(message, type, null));
}

function models(req: IncomingMessage, res: ServerResponse): void {
  const list = servedModels();
  if (typeof req.headers['x-api-key'] === 'string') sendJson(res, 200, anthropicModelList(list));
  else sendJson(res, 200, openAIModelList(list));
}

async function callUpstream(cand: Candidate, req: NormalizedRequest): Promise<{ ok: boolean; answer: NormalizedAnswer | null; permanentDead: boolean }> {
  const provider = cand.probe.provider;
  const base = joinBase(ENV_URL, provider.base);
  const url =
    provider.wire === 'openai'
      ? `${base}/v1/chat/completions`
      : provider.wire === 'anthropic'
        ? `${base}/v1/messages`
        : `${base}/v1beta/models/${encodeURIComponent(cand.model.id)}:generateContent`;
  const headers: Record<string, string> = {
    'content-type': 'application/json',
    accept: 'application/json',
    ...authHeaders(provider.auth, provider.key),
  };
  if (provider.wire === 'anthropic') headers['anthropic-version'] = '2023-06-01';
  const upstreamBody = buildUpstreamBody(provider.wire, cand.model.id, req);

  const res = await fetch(url, { method: 'POST', headers, body: JSON.stringify(upstreamBody) });
  const rawText = await res.text();
  if (res.ok) {
    let parsedJson: unknown = {};
    try {
      parsedJson = JSON.parse(rawText);
    } catch {
      parsedJson = {};
    }
    const answer = parseUpstreamAnswer(provider.wire, isRecord(parsedJson) ? parsedJson : {});
    return { ok: true, answer, permanentDead: false };
  }

  // Distinguish permanent exhaustion/outage ("budget is spent" / "is out") from single-call fail_calls ("refused this call")
  const permanentDead =
    res.status === 401 ||
    res.status === 403 ||
    rawText.includes('budget is spent') ||
    rawText.includes('is out');
  return { ok: false, answer: null, permanentDead };
}

async function serveInference(req: IncomingMessage, res: ServerResponse, clientApi: 'openai' | 'anthropic'): Promise<void> {
  const body = await readJson(req);
  if (body === null) return sendError(res, clientApi, 400, 'invalid_request_error', 'the request body is not one JSON object');

  const idx = manifestIndex;
  manifestIndex += 1;
  const manifestEntry = brief.workload?.manifest[idx];
  const parsed = parseClientRequest(clientApi, body);
  const requires = mergeRequirements(manifestEntry?.requires, parsed);
  const { candidates, topRating, weight } = rankCandidates(requires, parsed, idx, manifestEntry);

  if (candidates.length === 0) {
    return sendError(res, clientApi, 503, 'overloaded_error', 'no free model on the directory meets this request');
  }

  for (let pass = 0; pass < 3; pass++) {
    for (const cand of candidates) {
      const st = stateOf(cand.probe.provider.id);
      if (st.dead) continue;
      st.calls += 1;
      try {
        const outcome = await callUpstream(cand, parsed);
        if (outcome.ok && outcome.answer !== null) {
          st.lastCallFailed = false;
          const credit = Math.min(cand.rating, topRating);
          lossSoFar += weight * (topRating - credit);
          if (parsed.stream) {
            sendSse(res, emitClientSse(clientApi, outcome.answer, cand.model.id));
          } else {
            sendJson(res, 200, emitClientJson(clientApi, outcome.answer, cand.model.id));
          }
          return;
        }
        totalRefusals += 1;
        st.lastCallFailed = true;
        if (outcome.permanentDead) {
          st.dead = true;
        } else {
          st.transientFails += 1;
        }
      } catch {
        totalRefusals += 1;
        st.lastCallFailed = true;
        st.transientFails += 1;
      }
    }
  }

  sendError(res, clientApi, 503, 'overloaded_error', 'all candidate providers refused');
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://entry');
  if (req.method === 'GET' && url.pathname === '/v1/models') {
    models(req, res);
    return;
  }
  if (req.method === 'POST' && url.pathname === '/v1/chat/completions') {
    await serveInference(req, res, 'openai');
    return;
  }
  if (req.method === 'POST' && url.pathname === '/v1/messages') {
    await serveInference(req, res, 'anthropic');
    return;
  }
  sendError(res, url.pathname === '/v1/messages' ? 'anthropic' : 'openai', 404, 'not_found', `no route ${req.method ?? ''} ${url.pathname}`);
}

function listen(server: Server): Promise<void> {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '0.0.0.0', () => resolve());
  });
}

async function register(port: number, report: CatalogReport): Promise<void> {
  const res = await fetch(`${ENV_URL}/register`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ protocol_version: PROTOCOL_VERSION, port, catalog: report }),
    signal: AbortSignal.timeout(5000),
  });
  if (!res.ok) throw new Error(`POST ${ENV_URL}/register answered HTTP ${res.status}: ${(await res.text()).slice(0, 500)}`);
  const reply: unknown = await res.json();
  if (isRecord(reply) && typeof reply.requests === 'number') log(`registered: the workload holds ${reply.requests} requests`);
}

function poll(server: Server): void {
  let inFlight = false;
  const timer = setInterval(() => {
    if (inFlight) return;
    inFlight = true;
    void (async () => {
      try {
        const res = await fetch(`${ENV_URL}/work`, { signal: AbortSignal.timeout(2000) });
        if (res.status !== 200) return;
        const work: unknown = await res.json();
        if (isRecord(work) && work.done === true) {
          clearInterval(timer);
          server.close();
          process.exit(0);
        }
      } catch {
        // Retry on next tick.
      } finally {
        inFlight = false;
      }
    })();
  }, POLL_INTERVAL_MS);
}

async function start(): Promise<void> {
  await load();
  if (process.argv.includes('--list')) {
    const text = `${JSON.stringify(catalog)}\n`;
    await new Promise<void>((resolve) => process.stdout.write(text, () => resolve()));
    process.exit(0);
  }
  if (ENV_URL === '') throw new Error('MAKEFUN_ENV_URL is not set');
  const server = createServer((req, res) => {
    void handle(req, res).catch((err: unknown) => {
      log((err as Error).stack ?? String(err));
      if (!res.headersSent) sendError(res, req.url?.startsWith('/v1/messages') === true ? 'anthropic' : 'openai', 500, 'internal_error', 'the server failed to answer');
    });
  });
  await listen(server);
  const address = server.address();
  if (address === null || typeof address === 'string') throw new Error('the server has no port');
  const port = address.port;
  if (port === 8080) throw new Error('the OS picked 8080, which the env owns on one layout: restart the trial');
  log(`listening on 0.0.0.0:${port} with ${catalog.providers.length} answered providers and ${servedModels().length} free models`);
  await register(port, catalog);
  process.on('SIGTERM', () => process.exit(0));
  process.on('SIGINT', () => process.exit(0));
  poll(server);
}

try {
  await start();
} catch (err) {
  log((err as Error).stack ?? String(err));
  process.exit(1);
}

