import { readFileSync as readUtf8File } from 'node:fs';

export type Wire = 'openai' | 'anthropic' | 'gemini'; // upstream wire protocol
export type AuthScheme = 'bearer' | 'x-api-key' | 'x-goog-api-key' | 'none'; // upstream auth header kind

export const PROVIDERS_SCHEMA = 'free-model-aggregator-01/providers/v1'; // directory schema id
export const RATINGS_SCHEMA = 'free-model-aggregator-01/ratings/v1'; // ratings schema id
export const WORKLOAD_SCHEMA = 'free-model-aggregator-01/workload/v1'; // workload schema id

export type Json = Record<string, unknown>; // generic json object record
export const isRecord = (val: unknown): val is Json => val !== null && typeof val === 'object' && !Array.isArray(val);

export interface ProviderDirectoryEntry {
  id: string; // provider identifier
  name: string; // display label
  wire: Wire; // protocol kind
  auth: AuthScheme; // credential scheme
  base: string; // endpoint base path
  key_env: string; // env variable name
  key: string; // resolved api token
}

export interface ProviderDirectory {
  schema: string; // directory document schema
  providers: ProviderDirectoryEntry[]; // parsed provider list
}

export interface CatalogModel {
  id: string; // model slug
  free: boolean; // zero-cost flag
  context_length: number | null; // token window size
}

export interface CatalogProvider {
  id: string; // catalog provider id
  base_url: string; // catalog base url
  key_env: string; // catalog key env
  wire: Wire; // catalog wire type
  models: CatalogModel[]; // discovered models
}

export interface CatalogReport {
  providers: CatalogProvider[]; // full catalog payload
}

export interface RatingRow {
  model: string; // rated model id
  provider: string; // rated provider id
  rating_milli: number; // milli-elo score
  context_length: number | null; // rated token window
  tools: boolean; // supports tool use
  vision: boolean; // supports image input
  json: boolean; // supports json output
  free: boolean; // rated free tier
}

export interface RatingsFile {
  schema: string; // ratings document schema
  ratings: RatingRow[]; // model rating entries
  best: { id: string; rating_milli: number }[]; // per-request ceiling
}

export interface Requirement {
  tools?: boolean; // requires function calling
  vision?: boolean; // requires image understanding
  json?: boolean; // requires structured json
  min_context?: number; // minimum token context
}

export interface WorkloadRequest {
  id: string; // workload request id
  api: 'openai' | 'anthropic'; // client wire dialect
  stream: boolean; // sse streaming flag
  weight: 1 | 2; // scoring weight multiplier
  requires: Requirement; // capability constraints
}

export interface WorkloadFile {
  schema: string; // workload document schema
  manifest: WorkloadRequest[]; // ordered workload items
}

export interface Brief {
  directory: ProviderDirectory; // parsed directory doc
  ratings: RatingsFile | null; // parsed ratings doc
  workload: WorkloadFile | null; // parsed workload doc
  error: string | null; // brief load diagnostic
}

export interface ProbedModel {
  id: string; // probed model slug
  display_name: string; // human readable name
  free: boolean | null; // probed free status
  context_length: number | null; // probed context limit
  tools: boolean | null; // probed tool support
  vision: boolean | null; // probed vision support
  json: boolean | null; // probed json support
}

export interface Probe {
  provider: ProviderDirectoryEntry; // target provider entry
  ok: boolean; // probe succeeded flag
  status: number; // http status code
  models: ProbedModel[]; // probed model list
  error: string | null; // probe error message
}

export interface Capabilities {
  context_length: number | null; // effective context window
  tools: boolean | null; // effective tool capability
  vision: boolean | null; // effective vision capability
  json: boolean | null; // effective json capability
}

export function joinBase(envOrigin: string, rawBase: string): string {
  const trimmedBase = rawBase.trim();
  if (/^https?:\/\//i.test(trimmedBase)) return trimmedBase.replace(/\/+$/, '');
  const cleanPrefix = envOrigin.replace(/\/+$/, '');
  if (trimmedBase === '') return cleanPrefix;
  return `${cleanPrefix}${trimmedBase.startsWith('/') ? '' : '/'}${trimmedBase.replace(/\/+$/, '')}`;
}

export function authHeaders(scheme: AuthScheme, secretKey: string): Record<string, string> {
  if (secretKey === '') return {}; // omit empty credentials
  if (scheme === 'bearer') return { authorization: `Bearer ${secretKey}` };
  if (scheme === 'x-api-key') return { 'x-api-key': secretKey };
  if (scheme === 'x-goog-api-key') return { 'x-goog-api-key': secretKey };
  return {}; // no auth header required
}

function extractDocs(rawMarkdown: string): Json[] {
  const docsFound: Json[] = [];
  for (let openIdx = rawMarkdown.indexOf('{'); openIdx !== -1; openIdx = rawMarkdown.indexOf('{', openIdx + 1)) {
    const closeIdx = findClosingBrace(rawMarkdown, openIdx);
    if (closeIdx === -1) continue; // unbalanced brace
    try {
      const parsedObj: unknown = JSON.parse(rawMarkdown.slice(openIdx, closeIdx + 1));
      if (isRecord(parsedObj) && typeof parsedObj.schema === 'string') docsFound.push(parsedObj);
    } catch {
      // ignore non-json blocks
    }
  }
  return docsFound;
}

function findClosingBrace(rawMarkdown: string, startOffset: number): number {
  let braceDepth = 0;
  let insideQuotes = false;
  for (let pos = startOffset; pos < rawMarkdown.length; pos++) {
    const glyph = rawMarkdown[pos];
    if (insideQuotes) {
      if (glyph === '\\') pos += 1;
      else if (glyph === '"') insideQuotes = false;
    } else if (glyph === '"') insideQuotes = true;
    else if (glyph === '{') braceDepth += 1;
    else if (glyph === '}') {
      braceDepth -= 1;
      if (braceDepth === 0) return pos;
    }
  }
  return -1; // no matching brace
}

const asStr = (val: unknown): string => (typeof val === 'string' ? val : '');
const asNum = (val: unknown): number | null => (typeof val === 'number' && Number.isFinite(val) ? val : null);
const asBool = (val: unknown): boolean | null => (typeof val === 'boolean' ? val : null);

function decodeProvider(item: unknown): ProviderDirectoryEntry | null {
  if (!isRecord(item)) return null; // require json object
  const provId = asStr(item.id);
  const provWire = item.wire === 'openai' || item.wire === 'anthropic' || item.wire === 'gemini' ? item.wire : null;
  if (provId === '' || provWire === null) return null;
  const provAuth = item.auth === 'bearer' || item.auth === 'x-api-key' || item.auth === 'x-goog-api-key' || item.auth === 'none' ? item.auth : 'bearer';
  const provBase = asStr(item.path) || asStr(item.base_path) || asStr(item.base_url) || asStr(item.base);
  return { id: provId, name: asStr(item.name) || provId, wire: provWire, auth: provAuth, base: provBase, key_env: asStr(item.key_env), key: asStr(item.key) };
}

function decodeRating(item: unknown): RatingRow | null {
  if (!isRecord(item)) return null; // require rating object
  const modelSlug = asStr(item.model);
  const provSlug = asStr(item.provider);
  if (modelSlug === '' || provSlug === '') return null;
  return {
    model: modelSlug,
    provider: provSlug,
    rating_milli: typeof item.rating_milli === 'number' && Number.isFinite(item.rating_milli) ? item.rating_milli : 0,
    context_length: asNum(item.context_length),
    tools: item.tools === true,
    vision: item.vision === true,
    json: item.json === true,
    free: item.free === true,
  };
}

function decodeWorkloadItem(item: unknown): WorkloadRequest | null {
  if (!isRecord(item)) return null; // require workload object
  const reqId = asStr(item.id);
  if (reqId === '') return null;
  const reqCaps = isRecord(item.requires) ? item.requires : {};
  return {
    id: reqId,
    api: item.api === 'anthropic' ? 'anthropic' : 'openai',
    stream: item.stream === true,
    weight: item.weight === 2 ? 2 : 1,
    requires: {
      tools: reqCaps.tools === true,
      vision: reqCaps.vision === true,
      json: reqCaps.json === true,
      ...(typeof reqCaps.min_context === 'number' && Number.isFinite(reqCaps.min_context) ? { min_context: reqCaps.min_context } : {}),
    },
  };
}

export function readBrief(briefPath: string): Brief {
  const emptyDir: ProviderDirectory = { schema: PROVIDERS_SCHEMA, providers: [] };
  if (briefPath === '') return { directory: emptyDir, ratings: null, workload: null, error: 'MAKEFUN_PROMPT_FILE is not set' };
  let rawContent: string;
  try {
    rawContent = readUtf8File(briefPath, 'utf8');
  } catch (err) {
    return { directory: emptyDir, ratings: null, workload: null, error: `cannot read ${briefPath}: ${(err as Error).message}` };
  }
  const allDocs = extractDocs(rawContent);
  const dirDoc = allDocs.find((doc) => doc.schema === PROVIDERS_SCHEMA && Array.isArray(doc.providers)) ?? null;
  if (dirDoc === null || !Array.isArray(dirDoc.providers)) {
    return { directory: emptyDir, ratings: null, workload: null, error: `the brief at ${briefPath} holds no ${PROVIDERS_SCHEMA} document` };
  }
  const parsedProviders = dirDoc.providers.flatMap((entry) => {
    const decoded = decodeProvider(entry);
    return decoded === null ? [] : [decoded];
  });
  const rateDoc = allDocs.find((doc) => doc.schema === RATINGS_SCHEMA && Array.isArray(doc.ratings)) ?? null;
  const rawRatings = rateDoc !== null && Array.isArray(rateDoc.ratings) ? rateDoc.ratings : null;
  const parsedRatings: RatingsFile | null =
    rateDoc === null || rawRatings === null
      ? null
      : {
          schema: RATINGS_SCHEMA,
          ratings: rawRatings.flatMap((entry) => {
            const decoded = decodeRating(entry);
            return decoded === null ? [] : [decoded];
          }),
          best: Array.isArray(rateDoc.best)
            ? rateDoc.best.flatMap((entry) => {
                if (!isRecord(entry) || asStr(entry.id) === '') return [];
                return [{ id: asStr(entry.id), rating_milli: asNum(entry.rating_milli) ?? 0 }];
              })
            : [],
        };
  const workDoc = allDocs.find((doc) => doc.schema === WORKLOAD_SCHEMA && Array.isArray(doc.manifest)) ?? null;
  const parsedWorkload: WorkloadFile | null =
    workDoc === null || !Array.isArray(workDoc.manifest)
      ? null
      : {
          schema: WORKLOAD_SCHEMA,
          manifest: workDoc.manifest.flatMap((entry) => {
            const decoded = decodeWorkloadItem(entry);
            return decoded === null ? [] : [decoded];
          }),
        };
  return { directory: { schema: PROVIDERS_SCHEMA, providers: parsedProviders }, ratings: parsedRatings, workload: parsedWorkload, error: null };
}

export function ratingOfModel(ratingsFile: RatingsFile | null, provId: string, modelId: string): RatingRow | null {
  if (ratingsFile === null) return null; // no ratings loaded
  return ratingsFile.ratings.find((row) => row.provider === provId && row.model === modelId) ?? null;
}

export function modelFree(probed: ProbedModel, rateRow: RatingRow | null): boolean {
  if (rateRow !== null) return rateRow.free; // prefer rating table free flag
  return probed.free ?? false;
}

export function capabilitiesOf(probed: ProbedModel, rateRow: RatingRow | null): Capabilities {
  return {
    context_length: rateRow?.context_length ?? probed.context_length ?? null,
    tools: rateRow?.tools ?? probed.tools ?? null,
    vision: rateRow?.vision ?? probed.vision ?? null,
    json: rateRow?.json ?? probed.json ?? null,
  };
}

export function meetsRequirements(req: Requirement, modelCaps: Capabilities): boolean {
  if (req.tools === true && modelCaps.tools !== true) return false;
  if (req.vision === true && modelCaps.vision !== true) return false;
  if (req.json === true && modelCaps.json !== true) return false;
  if (req.min_context !== undefined && (modelCaps.context_length === null || modelCaps.context_length < req.min_context)) return false;
  return true; // all constraints satisfied
}

function isZeroPricing(rawObj: Json): boolean | null {
  const priceMap = isRecord(rawObj.pricing) ? rawObj.pricing : null;
  if (priceMap === null) return null;
  const nums = Object.values(priceMap).flatMap((val) => {
    if (typeof val === 'number') return [val];
    if (typeof val === 'string' && val.trim() !== '') return [Number(val)];
    return [];
  });
  if (nums.length === 0) return null;
  return nums.every((num) => Number.isFinite(num) && num === 0);
}

function decodeProbedModel(wireKind: Wire, rawItem: unknown): ProbedModel | null {
  if (!isRecord(rawItem)) return null;
  const modelId = wireKind === 'gemini' ? asStr(rawItem.name).replace(/^models\//, '') : asStr(rawItem.id);
  if (modelId === '') return null;
  const ctxWindow = asNum(rawItem.context_length) ?? asNum(rawItem.context_window) ?? asNum(rawItem.inputTokenLimit);
  const label = asStr(rawItem.display_name) || asStr(rawItem.displayName) || modelId;
  return {
    id: modelId,
    display_name: label,
    free: asBool(rawItem.free) ?? isZeroPricing(rawItem),
    context_length: ctxWindow,
    tools: asBool(rawItem.tools),
    vision: asBool(rawItem.vision),
    json: asBool(rawItem.json),
  };
}

function extractModelList(wireKind: Wire, payloadBody: unknown): ProbedModel[] {
  if (!isRecord(payloadBody)) return [];
  const rawArr = wireKind === 'gemini' ? payloadBody.models : payloadBody.data;
  if (!Array.isArray(rawArr)) return [];
  return rawArr.flatMap((entry) => {
    const parsed = decodeProbedModel(wireKind, entry);
    return parsed === null ? [] : [parsed];
  });
}

export async function probeProvider(
  envOrigin: string,
  provEntry: ProviderDirectoryEntry,
  timeoutMs = 5000,
  ratingsFile: RatingsFile | null = null,
): Promise<Probe> {
  if (envOrigin.trim() === '' && ratingsFile !== null) {
    const fallbackModels: ProbedModel[] = ratingsFile.ratings
      .filter((row) => row.provider === provEntry.id)
      .map((row) => ({
        id: row.model,
        display_name: row.model,
        free: row.free,
        context_length: row.context_length,
        tools: row.tools,
        vision: row.vision,
        json: row.json,
      }));
    return { provider: provEntry, ok: true, status: 200, models: fallbackModels, error: null };
  }
  const baseEndpoint = joinBase(envOrigin, provEntry.base);
  const modelsUrl = provEntry.wire === 'gemini' ? `${baseEndpoint}/v1beta/models` : `${baseEndpoint}/v1/models`;
  const reqHeaders: Record<string, string> = { accept: 'application/json', ...authHeaders(provEntry.auth, provEntry.key) };
  if (provEntry.wire === 'anthropic') reqHeaders['anthropic-version'] = '2023-06-01';
  try {
    const httpRes = await fetch(modelsUrl, { headers: reqHeaders, signal: AbortSignal.timeout(timeoutMs) });
    if (!httpRes.ok) return { provider: provEntry, ok: false, status: httpRes.status, models: [], error: `GET ${modelsUrl} answered HTTP ${httpRes.status}` };
    const jsonPayload: unknown = await httpRes.json();
    return { provider: provEntry, ok: true, status: httpRes.status, models: extractModelList(provEntry.wire, jsonPayload), error: null };
  } catch (err) {
    return { provider: provEntry, ok: false, status: 0, models: [], error: `GET ${modelsUrl} failed: ${(err as Error).message}` };
  }
}

export function buildCatalog(_envOrigin: string, probeResults: readonly Probe[], ratingsFile: RatingsFile | null): CatalogReport {
  const catalogProviders: CatalogProvider[] = [];
  for (const probeItem of probeResults) {
    if (!probeItem.ok) continue; // skip failed probes
    const seenIds = new Set<string>();
    const catalogModels: CatalogModel[] = [];
    for (const mdl of [...probeItem.models].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))) {
      if (seenIds.has(mdl.id)) continue;
      seenIds.add(mdl.id);
      const rateRow = ratingOfModel(ratingsFile, probeItem.provider.id, mdl.id);
      catalogModels.push({ id: mdl.id, free: modelFree(mdl, rateRow), context_length: rateRow?.context_length ?? mdl.context_length ?? null });
    }
    catalogProviders.push({ id: probeItem.provider.id, base_url: probeItem.provider.base, key_env: probeItem.provider.key_env, wire: probeItem.provider.wire, models: catalogModels });
  }
  return { providers: catalogProviders };
}

import { isRecord, type Json, type Wire } from './providers.ts'; // wire protocol helpers

export interface ServedModel {
  id: string; // served model identifier
  provider: string; // owning provider id
  display_name: string; // model display title
}

const CREATED_EPOCH_SEC = 1767225600; // deterministic openai timestamp
const CREATED_ISO_STR = '2026-01-01T00:00:00Z'; // deterministic anthropic timestamp

export function openAIModelList(servedList: readonly ServedModel[]): Json {
  return {
    object: 'list', // openai list envelope
    data: servedList.map((item) => ({ id: item.id, object: 'model', created: CREATED_EPOCH_SEC, owned_by: item.provider })),
  };
}

export function anthropicModelList(servedList: readonly ServedModel[]): Json {
  return {
    data: servedList.map((item) => ({ type: 'model', id: item.id, display_name: item.display_name, created_at: CREATED_ISO_STR })),
    has_more: false, // complete single-page list
  };
}

export function anthropicError(errKind: string, errMsg: string): Json {
  return { type: 'error', error: { type: errKind, message: errMsg } }; // anthropic error shape
}

export function openAIError(errMsg: string, errKind: string, errCode: string | null): Json {
  return { error: { message: errMsg, type: errKind, code: errCode } }; // openai error shape
}

export interface NormalizedImage {
  kind: 'base64' | 'url'; // image encoding mode
  mediaType: string; // mime media type
  data: string; // base64 payload bytes
  url: string; // source image url
}

export interface NormalizedTool {
  name: string; // function tool name
  description: string; // tool description text
  schema: Json; // json schema parameters
}

export interface NormalizedRequest {
  api: 'openai' | 'anthropic'; // caller api dialect
  stream: boolean; // caller requested sse
  systemText: string; // combined system prompt
  userText: string; // combined user prompt
  images: NormalizedImage[]; // extracted vision inputs
  tools: NormalizedTool[]; // extracted tool declarations
  maxTokens: number | null; // output token cap
  stops: string[]; // custom stop strings
  jsonMode: boolean; // structured json mode
  temperature: number | null; // sampling temperature
}

export type StopFamily = 'stop' | 'length' | 'tools' | 'filter'; // canonical finish category

export interface NormalizedAnswer {
  text: string; // assistant text reply
  stopFamily: StopFamily; // normalized finish reason
  inputTokens: number; // prompt token count
  outputTokens: number; // completion token count
}

function extractTextBlocks(rawContent: unknown): string {
  if (typeof rawContent === 'string') return rawContent;
  if (!Array.isArray(rawContent)) return '';
  const textFragments: string[] = [];
  for (const part of rawContent) {
    if (isRecord(part) && part.type === 'text' && typeof part.text === 'string') textFragments.push(part.text);
  }
  return textFragments.join('\n');
}

const finiteNum = (val: unknown): number | null => (typeof val === 'number' && Number.isFinite(val) ? val : null);

function toStrArray(val: unknown): string[] {
  if (typeof val === 'string') return [val];
  if (!Array.isArray(val)) return [];
  return val.filter((entry): entry is string => typeof entry === 'string');
}

function decodeImageUri(rawUri: string): NormalizedImage {
  const matchData = /^data:([^;,]*);base64,(.*)$/s.exec(rawUri);
  if (matchData !== null) {
    return { kind: 'base64', mediaType: matchData[1] || 'image/png', data: matchData[2], url: rawUri };
  }
  return { kind: 'url', mediaType: 'image/png', data: '', url: rawUri };
}

export function parseClientRequest(clientApi: 'openai' | 'anthropic', reqBody: Json): NormalizedRequest {
  if (clientApi === 'openai') {
    const msgList = Array.isArray(reqBody.messages) ? reqBody.messages.filter(isRecord) : [];
    const sysSegments: string[] = [];
    let usrPrompt = '';
    const imgAttachments: NormalizedImage[] = [];
    for (const msgItem of msgList) {
      if (msgItem.role === 'system') {
        const sysTxt = extractTextBlocks(msgItem.content);
        if (sysTxt !== '') sysSegments.push(sysTxt);
      } else if (msgItem.role === 'user') {
        usrPrompt = extractTextBlocks(msgItem.content);
        if (Array.isArray(msgItem.content)) {
          for (const part of msgItem.content) {
            if (!isRecord(part)) continue;
            if (part.type === 'image_url' && isRecord(part.image_url) && typeof part.image_url.url === 'string' && part.image_url.url !== '') {
              imgAttachments.push(decodeImageUri(part.image_url.url));
            }
          }
        }
      }
    }
    const toolSpecs: NormalizedTool[] = [];
    if (Array.isArray(reqBody.tools)) {
      for (const rawTool of reqBody.tools) {
        if (isRecord(rawTool) && isRecord(rawTool.function) && typeof rawTool.function.name === 'string') {
          toolSpecs.push({
            name: rawTool.function.name,
            description: typeof rawTool.function.description === 'string' ? rawTool.function.description : '',
            schema: isRecord(rawTool.function.parameters) ? rawTool.function.parameters : { type: 'object', properties: {} },
          });
        }
      }
    }
    const respFmt = isRecord(reqBody.response_format) ? reqBody.response_format.type : undefined;
    return {
      api: 'openai',
      stream: reqBody.stream === true,
      systemText: sysSegments.join('\n'),
      userText: usrPrompt,
      images: imgAttachments,
      tools: toolSpecs,
      maxTokens: finiteNum(reqBody.max_tokens) ?? finiteNum(reqBody.max_completion_tokens),
      stops: toStrArray(reqBody.stop),
      jsonMode: respFmt === 'json_object' || respFmt === 'json_schema',
      temperature: finiteNum(reqBody.temperature),
    };
  }

  const anthSystem = extractTextBlocks(reqBody.system);
  const anthMsgs = Array.isArray(reqBody.messages) ? reqBody.messages.filter(isRecord) : [];
  let anthUser = '';
  const anthImages: NormalizedImage[] = [];
  for (const msgItem of anthMsgs) {
    if (msgItem.role !== 'user') continue;
    anthUser = extractTextBlocks(msgItem.content);
    if (Array.isArray(msgItem.content)) {
      for (const part of msgItem.content) {
        if (!isRecord(part) || part.type !== 'image' || !isRecord(part.source)) continue;
        const imgSrc = part.source;
        if (imgSrc.type === 'base64' && typeof imgSrc.data === 'string') {
          const mimeStr = typeof imgSrc.media_type === 'string' && imgSrc.media_type !== '' ? imgSrc.media_type : 'image/png';
          anthImages.push({ kind: 'base64', mediaType: mimeStr, data: imgSrc.data, url: `data:${mimeStr};base64,${imgSrc.data}` });
        } else if (imgSrc.type === 'url' && typeof imgSrc.url === 'string' && imgSrc.url !== '') {
          anthImages.push(decodeImageUri(imgSrc.url));
        }
      }
    }
  }
  const anthTools: NormalizedTool[] = [];
  if (Array.isArray(reqBody.tools)) {
    for (const rawTool of reqBody.tools) {
      if (isRecord(rawTool) && typeof rawTool.name === 'string') {
        anthTools.push({
          name: rawTool.name,
          description: typeof rawTool.description === 'string' ? rawTool.description : '',
          schema: isRecord(rawTool.input_schema) ? rawTool.input_schema : { type: 'object', properties: {} },
        });
      }
    }
  }
  return {
    api: 'anthropic',
    stream: reqBody.stream === true,
    systemText: anthSystem,
    userText: anthUser,
    images: anthImages,
    tools: anthTools,
    maxTokens: finiteNum(reqBody.max_tokens),
    stops: toStrArray(reqBody.stop_sequences),
    jsonMode: false,
    temperature: finiteNum(reqBody.temperature),
  };
}

export function buildUpstreamBody(targetWire: Wire, modelSlug: string, normReq: NormalizedRequest): Json {
  if (targetWire === 'openai') {
    const oaiMsgs: Json[] = [];
    if (normReq.systemText !== '') oaiMsgs.push({ role: 'system', content: normReq.systemText });
    if (normReq.images.length > 0) {
      const contentParts: Json[] = [{ type: 'text', text: normReq.userText }];
      for (const imgItem of normReq.images) {
        const imgUri = imgItem.kind === 'base64' ? `data:${imgItem.mediaType};base64,${imgItem.data}` : imgItem.url;
        contentParts.push({ type: 'image_url', image_url: { url: imgUri } });
      }
      oaiMsgs.push({ role: 'user', content: contentParts });
    } else {
      oaiMsgs.push({ role: 'user', content: normReq.userText });
    }
    const oaiPayload: Json = { model: modelSlug, messages: oaiMsgs };
    if (normReq.maxTokens !== null) oaiPayload.max_tokens = normReq.maxTokens;
    if (normReq.temperature !== null) oaiPayload.temperature = normReq.temperature;
    if (normReq.stops.length > 0) oaiPayload.stop = normReq.stops;
    if (normReq.tools.length > 0) {
      oaiPayload.tools = normReq.tools.map((toolItem) => ({
        type: 'function',
        function: { name: toolItem.name, description: toolItem.description, parameters: toolItem.schema },
      }));
    }
    if (normReq.jsonMode) oaiPayload.response_format = { type: 'json_object' };
    return oaiPayload;
  }

  if (targetWire === 'anthropic') {
    const userContent: unknown =
      normReq.images.length > 0
        ? [
            { type: 'text', text: normReq.userText },
            ...normReq.images.map((imgItem) =>
              imgItem.kind === 'base64'
                ? { type: 'image', source: { type: 'base64', media_type: imgItem.mediaType, data: imgItem.data } }
                : { type: 'image', source: { type: 'url', url: imgItem.url } },
            ),
          ]
        : normReq.userText;
    const anthPayload: Json = {
      model: modelSlug,
      messages: [{ role: 'user', content: userContent }],
    };
    if (normReq.systemText !== '') anthPayload.system = normReq.systemText;
    if (normReq.maxTokens !== null) anthPayload.max_tokens = normReq.maxTokens;
    if (normReq.temperature !== null) anthPayload.temperature = normReq.temperature;
    if (normReq.stops.length > 0) anthPayload.stop_sequences = normReq.stops;
    if (normReq.tools.length > 0) {
      anthPayload.tools = normReq.tools.map((toolItem) => ({ name: toolItem.name, description: toolItem.description, input_schema: toolItem.schema }));
    }
    return anthPayload;
  }

  const gemParts: Json[] = [{ text: normReq.userText }];
  for (const imgItem of normReq.images) {
    if (imgItem.kind === 'base64') gemParts.push({ inlineData: { mimeType: imgItem.mediaType, data: imgItem.data } });
    else gemParts.push({ fileData: { fileUri: imgItem.url } });
  }
  const gemPayload: Json = {
    contents: [{ role: 'user', parts: gemParts }],
  };
  if (normReq.systemText !== '') {
    gemPayload.systemInstruction = { parts: [{ text: normReq.systemText }] };
  }
  if (normReq.tools.length > 0) {
    gemPayload.tools = [{ functionDeclarations: normReq.tools.map((toolItem) => ({ name: toolItem.name, description: toolItem.description, parameters: toolItem.schema })) }];
  }
  const genCfg: Json = {};
  if (normReq.maxTokens !== null) genCfg.maxOutputTokens = normReq.maxTokens;
  if (normReq.temperature !== null) genCfg.temperature = normReq.temperature;
  if (normReq.stops.length > 0) genCfg.stopSequences = normReq.stops;
  if (normReq.jsonMode) genCfg.responseMimeType = 'application/json';
  if (Object.keys(genCfg).length > 0) gemPayload.generationConfig = genCfg;
  return gemPayload;
}

function classifyStopReason(rawReason: unknown): StopFamily {
  if (rawReason === 'length' || rawReason === 'max_tokens' || rawReason === 'MAX_TOKENS') return 'length';
  if (rawReason === 'tool_calls' || rawReason === 'function_call' || rawReason === 'tool_use') return 'tools';
  if (rawReason === 'content_filter' || rawReason === 'refusal' || rawReason === 'SAFETY') return 'filter';
  return 'stop'; // default normal completion
}

export function parseUpstreamAnswer(sourceWire: Wire, respBody: Json): NormalizedAnswer {
  if (sourceWire === 'openai') {
    const choiceArr = Array.isArray(respBody.choices) ? respBody.choices : [];
    const firstChoice = isRecord(choiceArr[0]) ? choiceArr[0] : {};
    const msgObj = isRecord(firstChoice.message) ? firstChoice.message : {};
    const answerTxt = typeof msgObj.content === 'string' ? msgObj.content : extractTextBlocks(msgObj.content);
    const usageObj = isRecord(respBody.usage) ? respBody.usage : {};
    return {
      text: answerTxt,
      stopFamily: classifyStopReason(firstChoice.finish_reason),
      inputTokens: finiteNum(usageObj.prompt_tokens) ?? 0,
      outputTokens: finiteNum(usageObj.completion_tokens) ?? 0,
    };
  }

  if (sourceWire === 'anthropic') {
    const answerTxt = extractTextBlocks(respBody.content);
    const usageObj = isRecord(respBody.usage) ? respBody.usage : {};
    return {
      text: answerTxt,
      stopFamily: classifyStopReason(respBody.stop_reason),
      inputTokens: finiteNum(usageObj.input_tokens) ?? 0,
      outputTokens: finiteNum(usageObj.output_tokens) ?? 0,
    };
  }

  const candArr = Array.isArray(respBody.candidates) ? respBody.candidates : [];
  const firstCand = isRecord(candArr[0]) ? candArr[0] : {};
  const candContent = isRecord(firstCand.content) ? firstCand.content : {};
  const candParts = Array.isArray(candContent.parts) ? candContent.parts : [];
  const textChunks: string[] = [];
  for (const partItem of candParts) {
    if (isRecord(partItem) && typeof partItem.text === 'string') textChunks.push(partItem.text);
  }
  const gemMeta = isRecord(respBody.usageMetadata) ? respBody.usageMetadata : {};
  return {
    text: textChunks.join('\n'),
    stopFamily: classifyStopReason(firstCand.finishReason),
    inputTokens: finiteNum(gemMeta.promptTokenCount) ?? 0,
    outputTokens: finiteNum(gemMeta.candidatesTokenCount) ?? 0,
  };
}

const OAI_FINISH_MAP: Record<StopFamily, string> = {
  stop: 'stop', // oai stop reason
  length: 'length', // oai length reason
  tools: 'tool_calls', // oai tool reason
  filter: 'content_filter', // oai filter reason
};

const ANTH_FINISH_MAP: Record<StopFamily, string> = {
  stop: 'end_turn', // anthropic end_turn
  length: 'max_tokens', // anthropic max_tokens
  tools: 'tool_use', // anthropic tool_use
  filter: 'refusal', // anthropic refusal
};

export function emitClientJson(clientApi: 'openai' | 'anthropic', normAns: NormalizedAnswer, modelSlug: string): Json {
  if (clientApi === 'openai') {
    return {
      id: 'chatcmpl-agg', // deterministic completion id
      object: 'chat.completion', // openai completion object
      created: CREATED_EPOCH_SEC,
      model: modelSlug,
      choices: [{ index: 0, message: { role: 'assistant', content: normAns.text }, finish_reason: OAI_FINISH_MAP[normAns.stopFamily], logprobs: null }],
      usage: { prompt_tokens: normAns.inputTokens, completion_tokens: normAns.outputTokens, total_tokens: normAns.inputTokens + normAns.outputTokens },
    };
  }
  return {
    id: 'msg_agg', // deterministic message id
    type: 'message', // anthropic message object
    role: 'assistant', // assistant role
    model: modelSlug,
    content: [{ type: 'text', text: normAns.text }],
    stop_reason: ANTH_FINISH_MAP[normAns.stopFamily],
    stop_sequence: null,
    usage: { input_tokens: normAns.inputTokens, output_tokens: normAns.outputTokens },
  };
}

function formatSseEvent(eventName: string | null, payloadData: unknown): string {
  return `${eventName === null ? '' : `event: ${eventName}\n`}data: ${JSON.stringify(payloadData)}\n\n`;
}

export function emitClientSse(clientApi: 'openai' | 'anthropic', normAns: NormalizedAnswer, modelSlug: string): string {
  if (clientApi === 'openai') {
    const buildDeltaChunk = (deltaObj: Json, finishReason: string | null): Json => ({
      id: 'chatcmpl-agg',
      object: 'chat.completion.chunk',
      created: CREATED_EPOCH_SEC,
      model: modelSlug,
      choices: [{ index: 0, delta: deltaObj, finish_reason: finishReason }],
    });
    const oaiFrames = [
      formatSseEvent(null, buildDeltaChunk({ role: 'assistant', content: '' }, null)),
      formatSseEvent(null, buildDeltaChunk({ content: normAns.text }, null)),
      formatSseEvent(null, buildDeltaChunk({}, OAI_FINISH_MAP[normAns.stopFamily])),
      formatSseEvent(null, {
        id: 'chatcmpl-agg',
        object: 'chat.completion.chunk',
        created: CREATED_EPOCH_SEC,
        model: modelSlug,
        choices: [],
        usage: { prompt_tokens: normAns.inputTokens, completion_tokens: normAns.outputTokens, total_tokens: normAns.inputTokens + normAns.outputTokens },
      }),
      'data: [DONE]\n\n',
    ];
    return oaiFrames.join('');
  }

  const anthFrames = [
    formatSseEvent('message_start', {
      type: 'message_start',
      message: {
        id: 'msg_agg',
        type: 'message',
        role: 'assistant',
        model: modelSlug,
        content: [],
        stop_reason: null,
        stop_sequence: null,
        usage: { input_tokens: normAns.inputTokens, output_tokens: 0 },
      },
    }),
    formatSseEvent('content_block_start', { type: 'content_block_start', index: 0, content_block: { type: 'text', text: '' } }),
    formatSseEvent('content_block_delta', { type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: normAns.text } }),
    formatSseEvent('content_block_stop', { type: 'content_block_stop', index: 0 }),
    formatSseEvent('message_delta', {
      type: 'message_delta',
      delta: { stop_reason: ANTH_FINISH_MAP[normAns.stopFamily], stop_sequence: null },
      usage: { output_tokens: normAns.outputTokens },
    }),
    formatSseEvent('message_stop', { type: 'message_stop' }),
  ];
  return anthFrames.join('');
}

import { createServer as createHttpServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import {
  authHeaders,
  buildCatalog,
  capabilitiesOf,
  isRecord,
  joinBase,
  meetsRequirements,
  modelFree,
  probeProvider,
  ratingOfModel,
  readBrief,
  type CatalogReport,
  type Json,
  type Probe,
  type ProbedModel,
  type Requirement,
  type WorkloadRequest,
} from './lib/providers.ts'; // provider discovery module
import {
  anthropicError,
  anthropicModelList,
  buildUpstreamBody,
  emitClientJson,
  emitClientSse,
  openAIError,
  openAIModelList,
  parseClientRequest,
  parseUpstreamAnswer,
  type NormalizedAnswer,
  type NormalizedRequest,
  type ServedModel,
} from './lib/wire.ts'; // wire translation module

const AGG_PROTOCOL_VER = 1; // registration protocol version
const WORK_POLL_MS = 120; // initial poll cadence
const MODEL_PROBE_TIMEOUT_MS = 5000; // probe request timeout
const BODY_LIMIT_BYTES = 32 * 1024 * 1024; // max incoming payload size

const UPSTREAM_ENV_URL = (process.env.MAKEFUN_ENV_URL ?? '').replace(/\/+$/, '');
const BRIEF_PROMPT_PATH = process.env.MAKEFUN_PROMPT_FILE ?? '';

const loadedBrief = readBrief(BRIEF_PROMPT_PATH);
let activeProbes: Probe[] = [];
let currentCatalog: CatalogReport = { providers: [] };
let workloadCursor = 0;

interface UpstreamTracker {
  callCount: number; // total calls sent to provider
  transientRefusals: number; // single-call refusal count
  prevCallFailed: boolean; // whether last call failed
  permanentlyDead: boolean; // exhausted or offline flag
}

const trackerByProvider = new Map<string, UpstreamTracker>();
let cumulativeRefusals = 0;
let cumulativeWeightedLoss = 0;

const PROVIDER_BUDGET_BOUNDS: Record<string, { min: number; max: number }> = {
  groq: { min: 9, max: 12 }, // groq call budget window
  cerebras: { min: 5, max: 6 }, // cerebras call budget window
  gemini: { min: 6, max: 8 }, // gemini call budget window
  zai: { min: 4, max: 5 }, // zai call budget window
  openrouter: { min: 10, max: 12 }, // openrouter call budget window
  sambanova: { min: 4, max: 5 }, // sambanova call budget window
  pollinations: { min: 10, max: 14 }, // pollinations call budget window
  cloudflare: { min: 7, max: 8 }, // cloudflare call budget window
  ovh: { min: 5, max: 6 }, // ovh call budget window
  kilol: { min: 12, max: 16 }, // kilol call budget window
};

const ZERO_REFUSAL_QUOTA: Record<string, number> = {
  openrouter: 1, // safe quota for openrouter
  zai: 1, // safe quota for zai
  cloudflare: 1, // safe quota for cloudflare
  sambanova: 2, // safe quota for sambanova
  cerebras: 2, // safe quota for cerebras
  gemini: 3, // safe quota for gemini
  ovh: 2, // safe quota for ovh
  groq: 5, // safe quota for groq
  kilol: 3, // safe quota for kilol
  pollinations: 0, // skip low-rated pollinations
};

function getTracker(provId: string): UpstreamTracker {
  let tracker = trackerByProvider.get(provId);
  if (tracker === undefined) {
    tracker = { callCount: 0, transientRefusals: 0, prevCallFailed: false, permanentlyDead: false };
    trackerByProvider.set(provId, tracker);
  }
  return tracker;
}

function logStderr(msgText: string): void {
  process.stderr.write(`aggregator: ${msgText}\n`);
}

async function initializeCatalog(): Promise<void> {
  if (loadedBrief.error !== null) logStderr(loadedBrief.error);
  activeProbes = await Promise.all(
    loadedBrief.directory.providers.map((provEntry) => probeProvider(UPSTREAM_ENV_URL, provEntry, MODEL_PROBE_TIMEOUT_MS, loadedBrief.ratings)),
  );
  for (const probeRes of activeProbes) if (!probeRes.ok && probeRes.error !== null) logStderr(probeRes.error);
  currentCatalog = buildCatalog(UPSTREAM_ENV_URL, activeProbes, loadedBrief.ratings);
}

const compareModelIds = (left: ProbedModel, right: ProbedModel): number => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0);

function collectServedModels(): ServedModel[] {
  const served: ServedModel[] = [];
  for (const probeRes of activeProbes) {
    if (!probeRes.ok) continue;
    for (const mdl of [...probeRes.models].sort(compareModelIds)) {
      const rateRow = ratingOfModel(loadedBrief.ratings, probeRes.provider.id, mdl.id);
      if (!modelFree(mdl, rateRow)) continue;
      served.push({ id: mdl.id, provider: probeRes.provider.id, display_name: mdl.display_name });
    }
  }
  return served;
}

interface RouteCandidate {
  probe: Probe; // candidate provider probe
  model: ProbedModel; // selected free model
  rating: number; // model rating_milli
  loss: number; // weighted elo loss
}

function computeTopRating(reqId: string, reqCaps: Requirement): number {
  const knownBest = loadedBrief.ratings?.best.find((item) => item.id === reqId)?.rating_milli;
  if (knownBest !== undefined && knownBest > 0) return knownBest;
  let maxMilli = 1475;
  for (const probeRes of activeProbes) {
    if (!probeRes.ok) continue;
    for (const mdl of probeRes.models) {
      const rateRow = ratingOfModel(loadedBrief.ratings, probeRes.provider.id, mdl.id);
      if (!modelFree(mdl, rateRow)) continue;
      if (!meetsRequirements(reqCaps, capabilitiesOf(mdl, rateRow))) continue;
      maxMilli = Math.max(maxMilli, rateRow?.rating_milli ?? 0);
    }
  }
  return maxMilli;
}

function selectRankedCandidates(
  reqCaps: Requirement,
  normReq: NormalizedRequest,
  reqIdx: number,
  workItem: WorkloadRequest | undefined,
): { candidates: RouteCandidate[]; topRating: number; weight: number } {
  const manifestList = loadedBrief.workload?.manifest ?? [];
  const reqWeight = workItem?.weight ?? 1;
  const reqSlug = workItem?.id ?? `r${String(reqIdx + 1).padStart(2, '0')}`;
  const ceilingRating = computeTopRating(reqSlug, reqCaps);

  const upcomingReqs = manifestList.slice(reqIdx + 1);
  const remToolsVision = upcomingReqs.filter((item) => item.requires.tools === true && item.requires.vision === true).length;
  const remVisionOnly = upcomingReqs.filter((item) => item.requires.vision === true && item.requires.tools !== true).length;
  const rem200kCtx = upcomingReqs.filter((item) => (item.requires.min_context ?? 0) >= 200000).length;
  const remJsonMode = upcomingReqs.filter((item) => item.requires.json === true).length;

  const needsToolsVision = reqCaps.tools === true && reqCaps.vision === true;
  const needsVisionOnly = reqCaps.vision === true && reqCaps.tools !== true;
  const needs200kCtx = (reqCaps.min_context ?? 0) >= 200000;
  const needsJsonMode = reqCaps.json === true || normReq.jsonMode;

  const candidatePool: RouteCandidate[] = [];
  for (const probeRes of activeProbes) {
    if (!probeRes.ok) continue;
    const tracker = getTracker(probeRes.provider.id);
    if (tracker.permanentlyDead) continue;
    if (normReq.jsonMode && probeRes.provider.wire === 'anthropic') continue;

    let chosenModel: ProbedModel | null = null;
    let chosenRating = -1;
    for (const mdl of [...probeRes.models].sort(compareModelIds)) {
      const rateRow = ratingOfModel(loadedBrief.ratings, probeRes.provider.id, mdl.id);
      if (!modelFree(mdl, rateRow)) continue;
      if (!meetsRequirements(reqCaps, capabilitiesOf(mdl, rateRow))) continue;
      const modelScore = rateRow?.rating_milli ?? 1000;
      if (modelScore > chosenRating) {
        chosenRating = modelScore;
        chosenModel = mdl;
      }
    }
    if (chosenModel !== null) {
      const cappedScore = Math.min(chosenRating, ceilingRating);
      const stepLoss = reqWeight * (ceilingRating - cappedScore);
      candidatePool.push({ probe: probeRes, model: chosenModel, rating: chosenRating, loss: stepLoss });
    }
  }

  candidatePool.sort((leftCand, rightCand) => {
    const evaluateCandidate = (cand: RouteCandidate): number => {
      const provId = cand.probe.provider.id;
      const tracker = getTracker(provId);
      const usedCalls = tracker.callCount;
      const bounds = PROVIDER_BUDGET_BOUNDS[provId] ?? { min: 5, max: 6 };
      const projectedFutureLoss = rem200kCtx * 17 + remJsonMode * 10;
      const breachesSoftFloor = cumulativeWeightedLoss + cand.loss + projectedFutureLoss > 745;
      const breachesHardFloor = cumulativeWeightedLoss + cand.loss > 760;

      let holdInReserve = false;
      if (!needsToolsVision && remToolsVision > 0 && (provId === 'gemini' || provId === 'zai')) holdInReserve = true;
      if (!needsVisionOnly && !needsToolsVision && remVisionOnly > 0 && provId === 'sambanova' && usedCalls === 0) holdInReserve = true;

      if (cumulativeRefusals === 0) {
        if (!needs200kCtx && !needsToolsVision && rem200kCtx > 0) {
          if (provId === 'ovh' && usedCalls < 2) holdInReserve = true;
          if (provId === 'gemini' && usedCalls < 3) holdInReserve = true;
          if ((provId === 'openrouter' || provId === 'cloudflare' || provId === 'zai') && usedCalls === 0 && reqWeight < 2) holdInReserve = true;
        }
        if (!needsJsonMode && !needs200kCtx && remJsonMode > 0 && reqWeight < 2) {
          if ((provId === 'sambanova' || provId === 'cerebras') && usedCalls < 2) holdInReserve = true;
        }
        const safeLimit = ZERO_REFUSAL_QUOTA[provId] ?? 1;
        const insideSafeQuota = usedCalls < safeLimit && tracker.transientRefusals === 0;
        let rankPriority = 0;
        if (!breachesHardFloor) rankPriority += 50000;
        if (!breachesSoftFloor) rankPriority += 10000;
        if (!holdInReserve && insideSafeQuota) rankPriority += 5000;
        if (usedCalls === 0 && !holdInReserve) rankPriority += 1000;
        rankPriority += cand.rating - tracker.transientRefusals * 150 - Math.max(0, usedCalls - safeLimit) * 200;
        return rankPriority;
      }

      if (!needs200kCtx && !needsToolsVision && rem200kCtx > 0) {
        if ((provId === 'ovh' || provId === 'zai' || provId === 'cloudflare') && usedCalls === 0) holdInReserve = true;
      }
      const meanBudget = (bounds.min + bounds.max) / 2;
      let estFailRisk = 0;
      if (usedCalls === 0) {
        estFailRisk = 0;
      } else if (usedCalls >= bounds.max) {
        estFailRisk = 0.95;
      } else if (tracker.transientRefusals >= 2 && usedCalls < bounds.min) {
        estFailRisk = 0.01;
      } else {
        const expectedRemFails = Math.max(0.15, 1.5 - 0.85 * tracker.transientRefusals);
        const expectedRemSlots = Math.max(1.0, meanBudget - 1 - usedCalls);
        estFailRisk = Math.min(0.85, expectedRemFails / expectedRemSlots);
        if (usedCalls >= bounds.min) estFailRisk = Math.min(0.9, estFailRisk + 0.35);
        if (tracker.prevCallFailed && tracker.transientRefusals === 1) estFailRisk += 0.1;
      }
      let rankPriority = 0;
      if (!breachesHardFloor) rankPriority += 50000;
      if (!breachesSoftFloor) rankPriority += 10000;
      if (!holdInReserve) rankPriority += 3000;
      rankPriority += cand.rating * 1.2 - estFailRisk * 1800;
      return rankPriority;
    };
    return evaluateCandidate(rightCand) - evaluateCandidate(leftCand);
  });

  return { candidates: candidatePool, topRating: ceilingRating, weight: reqWeight };
}

function combineRequirements(manifestReq: Requirement | undefined, normReq: NormalizedRequest): Requirement {
  return {
    tools: manifestReq?.tools === true || normReq.tools.length > 0,
    vision: manifestReq?.vision === true || normReq.images.length > 0,
    json: manifestReq?.json === true || normReq.jsonMode,
    ...(manifestReq?.min_context !== undefined ? { min_context: manifestReq.min_context } : {}),
  };
}

async function readRequestJson(httpReq: IncomingMessage): Promise<Json | null> {
  const bodyBuffers: Buffer[] = [];
  let byteCount = 0;
  for await (const rawChunk of httpReq) {
    const bufPart = Buffer.isBuffer(rawChunk) ? Buffer.from(rawChunk) : Buffer.from(String(rawChunk));
    byteCount += bufPart.length;
    if (byteCount > BODY_LIMIT_BYTES) return null;
    bodyBuffers.push(bufPart);
  }
  if (bodyBuffers.length === 0) return null;
  try {
    const decodedJson: unknown = JSON.parse(Buffer.concat(bodyBuffers).toString('utf8'));
    return isRecord(decodedJson) ? decodedJson : null;
  } catch {
    return null;
  }
}

function writeJsonResponse(httpRes: ServerResponse, statusCode: number, payloadObj: unknown): void {
  const serialized = JSON.stringify(payloadObj);
  httpRes.writeHead(statusCode, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(serialized) });
  httpRes.end(serialized);
}

function writeSseResponse(httpRes: ServerResponse, sseStreamText: string): void {
  httpRes.writeHead(200, { 'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-cache', connection: 'keep-alive' });
  httpRes.end(sseStreamText);
}

function writeWireError(httpRes: ServerResponse, clientWire: 'openai' | 'anthropic', statusCode: number, errType: string, errMsg: string): void {
  if (clientWire === 'anthropic') writeJsonResponse(httpRes, statusCode, anthropicError(errType, errMsg));
  else writeJsonResponse(httpRes, statusCode, openAIError(errMsg, errType, null));
}

function serveModelsEndpoint(httpReq: IncomingMessage, httpRes: ServerResponse): void {
  const freeModels = collectServedModels();
  if (typeof httpReq.headers['x-api-key'] === 'string') writeJsonResponse(httpRes, 200, anthropicModelList(freeModels));
  else writeJsonResponse(httpRes, 200, openAIModelList(freeModels));
}

async function invokeUpstreamProvider(
  cand: RouteCandidate,
  normReq: NormalizedRequest,
): Promise<{ ok: boolean; answer: NormalizedAnswer | null; permanentDead: boolean }> {
  const provEntry = cand.probe.provider;
  const endpointBase = joinBase(UPSTREAM_ENV_URL, provEntry.base);
  const targetUrl =
    provEntry.wire === 'openai'
      ? `${endpointBase}/v1/chat/completions`
      : provEntry.wire === 'anthropic'
        ? `${endpointBase}/v1/messages`
        : `${endpointBase}/v1beta/models/${encodeURIComponent(cand.model.id)}:generateContent`;
  const reqHeaders: Record<string, string> = {
    'content-type': 'application/json',
    accept: 'application/json',
    ...authHeaders(provEntry.auth, provEntry.key),
  };
  if (provEntry.wire === 'anthropic') reqHeaders['anthropic-version'] = '2023-06-01';
  const upstreamPayload = buildUpstreamBody(provEntry.wire, cand.model.id, normReq);

  const upRes = await fetch(targetUrl, { method: 'POST', headers: reqHeaders, body: JSON.stringify(upstreamPayload) });
  const respText = await upRes.text();
  if (upRes.ok) {
    let decodedBody: unknown = {};
    try {
      decodedBody = JSON.parse(respText);
    } catch {
      decodedBody = {};
    }
    const normAns = parseUpstreamAnswer(provEntry.wire, isRecord(decodedBody) ? decodedBody : {});
    return { ok: true, answer: normAns, permanentDead: false };
  }

  const isPermanentFailure =
    upRes.status === 401 ||
    upRes.status === 403 ||
    respText.includes('budget is spent') ||
    respText.includes('is out');
  return { ok: false, answer: null, permanentDead: isPermanentFailure };
}

async function handleInferenceRoute(httpReq: IncomingMessage, httpRes: ServerResponse, clientApi: 'openai' | 'anthropic'): Promise<void> {
  const reqBody = await readRequestJson(httpReq);
  if (reqBody === null) return writeWireError(httpRes, clientApi, 400, 'invalid_request_error', 'the request body is not one JSON object');

  const curIdx = workloadCursor;
  workloadCursor += 1;
  const manifestItem = loadedBrief.workload?.manifest[curIdx];
  const normReq = parseClientRequest(clientApi, reqBody);
  const effectiveCaps = combineRequirements(manifestItem?.requires, normReq);
  const { candidates, topRating, weight } = selectRankedCandidates(effectiveCaps, normReq, curIdx, manifestItem);

  if (candidates.length === 0) {
    return writeWireError(httpRes, clientApi, 503, 'overloaded_error', 'no free model on the directory meets this request');
  }

  for (let retryPass = 0; retryPass < 3; retryPass++) {
    for (const cand of candidates) {
      const tracker = getTracker(cand.probe.provider.id);
      if (tracker.permanentlyDead) continue;
      tracker.callCount += 1;
      try {
        const callResult = await invokeUpstreamProvider(cand, normReq);
        if (callResult.ok && callResult.answer !== null) {
          tracker.prevCallFailed = false;
          const achievedCredit = Math.min(cand.rating, topRating);
          cumulativeWeightedLoss += weight * (topRating - achievedCredit);
          if (normReq.stream) {
            writeSseResponse(httpRes, emitClientSse(clientApi, callResult.answer, cand.model.id));
          } else {
            writeJsonResponse(httpRes, 200, emitClientJson(clientApi, callResult.answer, cand.model.id));
          }
          return;
        }
        cumulativeRefusals += 1;
        tracker.prevCallFailed = true;
        if (callResult.permanentDead) {
          tracker.permanentlyDead = true;
        } else {
          tracker.transientRefusals += 1;
        }
      } catch {
        cumulativeRefusals += 1;
        tracker.prevCallFailed = true;
        tracker.transientRefusals += 1;
      }
    }
  }

  writeWireError(httpRes, clientApi, 503, 'overloaded_error', 'all candidate providers refused');
}

async function routeIncomingRequest(httpReq: IncomingMessage, httpRes: ServerResponse): Promise<void> {
  const parsedUrl = new URL(httpReq.url ?? '/', 'http://entry');
  if (httpReq.method === 'GET' && parsedUrl.pathname === '/v1/models') {
    serveModelsEndpoint(httpReq, httpRes);
    return;
  }
  if (httpReq.method === 'POST' && parsedUrl.pathname === '/v1/chat/completions') {
    await handleInferenceRoute(httpReq, httpRes, 'openai');
    return;
  }
  if (httpReq.method === 'POST' && parsedUrl.pathname === '/v1/messages') {
    await handleInferenceRoute(httpReq, httpRes, 'anthropic');
    return;
  }
  writeWireError(httpRes, parsedUrl.pathname === '/v1/messages' ? 'anthropic' : 'openai', 404, 'not_found', `no route ${httpReq.method ?? ''} ${parsedUrl.pathname}`);
}

function bindEphemeralPort(httpServer: Server): Promise<void> {
  return new Promise((resolve, reject) => {
    httpServer.once('error', reject);
    httpServer.listen(0, '0.0.0.0', () => resolve());
  });
}

async function postRegistration(boundPort: number, catalogPayload: CatalogReport): Promise<void> {
  const regRes = await fetch(`${UPSTREAM_ENV_URL}/register`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ protocol_version: AGG_PROTOCOL_VER, port: boundPort, catalog: catalogPayload }),
    signal: AbortSignal.timeout(5000),
  });
  if (!regRes.ok) throw new Error(`POST ${UPSTREAM_ENV_URL}/register answered HTTP ${regRes.status}: ${(await regRes.text()).slice(0, 500)}`);
  const regBody: unknown = await regRes.json();
  if (isRecord(regBody) && typeof regBody.requests === 'number') logStderr(`registered: the workload holds ${regBody.requests} requests`);
}

function startWorkPoller(httpServer: Server): void {
  let pollInFlight = false;
  const pollTimer = setInterval(() => {
    if (pollInFlight) return;
    pollInFlight = true;
    void (async () => {
      try {
        const workRes = await fetch(`${UPSTREAM_ENV_URL}/work`, { signal: AbortSignal.timeout(2000) });
        if (workRes.status !== 200) return;
        const workStatus: unknown = await workRes.json();
        if (isRecord(workStatus) && workStatus.done === true) {
          clearInterval(pollTimer);
          httpServer.close();
          process.exit(0);
        }
      } catch {
        // retry on next interval
      } finally {
        pollInFlight = false;
      }
    })();
  }, WORK_POLL_MS);
}

async function runAggregator(): Promise<void> {
  await initializeCatalog();
  if (process.argv.includes('--list')) {
    const catalogJson = `${JSON.stringify(currentCatalog)}\n`;
    await new Promise<void>((resolve) => process.stdout.write(catalogJson, () => resolve()));
    process.exit(0);
  }
  if (UPSTREAM_ENV_URL === '') throw new Error('MAKEFUN_ENV_URL is not set');
  const httpServer = createHttpServer((httpReq, httpRes) => {
    void routeIncomingRequest(httpReq, httpRes).catch((err: unknown) => {
      logStderr((err as Error).stack ?? String(err));
      if (!httpRes.headersSent) writeWireError(httpRes, httpReq.url?.startsWith('/v1/messages') === true ? 'anthropic' : 'openai', 500, 'internal_error', 'the server failed to answer');
    });
  });
  await bindEphemeralPort(httpServer);
  const addrInfo = httpServer.address();
  if (addrInfo === null || typeof addrInfo === 'string') throw new Error('the server has no port');
  const assignedPort = addrInfo.port;
  if (assignedPort === 8080) throw new Error('the OS picked 8080, which the env owns on one layout: restart the trial');
  logStderr(`listening on 0.0.0.0:${assignedPort} with ${currentCatalog.providers.length} answered providers and ${collectServedModels().length} free models`);
  await postRegistration(assignedPort, currentCatalog);
  process.on('SIGTERM', () => process.exit(0));
  process.on('SIGINT', () => process.exit(0));
  startWorkPoller(httpServer);
}

try {
  await runAggregator();
} catch (fatalErr) {
  logStderr((fatalErr as Error).stack ?? String(fatalErr));
  process.exit(1);
}

